/* (2026-11-24) Kawanabe Kyōsai, Farting Upsets a Game of Go (The Cleveland Museum of Art 1991.125.k) */
(T => { const A = {"kyosai": {"ja": {"title": "おならで碁がひっくり返る（画帖より）", "artist": "河鍋暁斎", "date": "1800年代半ば〜後半", "place": "日本（江戸〜明治時代）", "game": "囲碁", "medium": "画帖（折本、26の見開き）のうち一図。紙本墨画淡彩", "size": "画帖（閉じた状態）28×18cm", "credit": "アン・ダフェイとアンソニー・ダフェイ寄贈（エヴァン・ターナーをたたえて）", "p": ["幕末から明治にかけて活躍した絵師・河鍋暁斎（1831〜1889年）の画帖の一場面です。折りたたみ式の画帖に、筆の勢いにまかせた素早い墨の線で描かれています。暁斎は狩野派の確かな技を持ちながら、妖怪や戯画、風刺画でも人気を集めました。", "美術館の付けた題は「おならが碁をひっくり返す」。左の烏帽子の男が身をかがめた先で、右では碁盤が宙に舞い、碁笥から碁石が雨のようにこぼれ、相手の男はひっくり返っています。真剣勝負の碁を、たった一発で台なしにするばかばかしさ。昔の絵巻にも描かれた「屁」の笑いを、暁斎らしいすばやい筆で描いています。"], "spots": [["烏帽子の男", "身をかがめてお尻を突き出す男。騒ぎのもとでしょうか。"], ["宙に舞う碁盤", "升目の碁盤が、ななめに吹き飛んでいます。"], ["碁笥と碁石", "碁石を入れる碁笥が2つ、ひっくり返って石が降りそそぎます。"], ["扇", "碁盤のそばに、開いた扇も飛ばされています。"], ["ひっくり返った相手", "あおむけに倒れて、目を丸くする男。"], ["筆の線", "下描きなしで一気に引いたような、勢いのある墨の線。"]]}, "en": {"title": "Farting Upsets a Game of Go (from a sketch album)", "artist": "Kawanabe Kyōsai", "date": "Mid- to late 1800s", "place": "Japan (Edo to Meiji period)", "game": "Go", "medium": "One opening of an accordion-style album of 26 double leaves; ink and color on paper", "size": "Album (closed) 28 × 18 cm", "credit": "Given by Anne and Anthony d’Offay in honor of Evan Turner", "p": ["A scene from a sketch album by Kawanabe Kyōsai (1831–1889), a painter active from the last years of the shoguns into the Meiji era, drawn in quick, free brushstrokes on the pages of a folding album. Trained in the Kanō school’s exacting technique, Kyōsai was also loved for his demons, caricatures and satire.", "The museum’s title says it all: “Farting Upsets a Game of Go.” On the left a man in a tall black cap bends over; on the right the go board flies through the air, the stone bowls rain stones, and his opponent is knocked flat on his back. A serious game ruined in a single blast — Kyōsai sets the old Japanese tradition of fart humor, already found in medieval scrolls, down with his rapid brush."], "spots": [["The man in the black cap", "Bent over, his backside thrust out — the cause of the trouble?"], ["The flying board", "The ruled go board sails off at an angle."], ["The bowls and stones", "Two stone bowls tumble, and the stones pour down."], ["The fan", "An open fan is blown away beside the board."], ["The toppled opponent", "Flat on his back, eyes wide."], ["The brushwork", "Strong ink lines, as if drawn in one go without a sketch."]]}, "zh": {"title": "一个屁掀翻了棋局（画册选页）", "artist": "河锅晓斋", "date": "19世纪中后期", "place": "日本（江户—明治时代）", "game": "围棋", "medium": "折页画册（26个对开页）之一；纸本墨笔淡彩", "size": "画册（合起）28×18厘米", "credit": "安妮与安东尼·多费捐赠（纪念埃文·特纳）", "p": ["这是活跃于幕末至明治的画家河锅晓斋（1831—1889年）画册中的一页，用迅疾奔放的墨线画在折页画册上。晓斋受过狩野派严格的训练，同时以妖怪画、戏画和讽刺画广受欢迎。", "美术馆的标题就说明了一切：“一个屁掀翻了棋局”。左边戴乌帽子的男人弯下腰，右边的棋盘飞上半空，棋罐里的棋子如雨洒落，对手仰面跌倒。认真的对局被一下子毁掉——晓斋用他飞快的笔，画出了日本自古画卷中就有的“屁”的笑料。"], "spots": [["戴乌帽子的男人", "弯腰撅臀的男人，大概就是祸首。"], ["飞起的棋盘", "画着格子的棋盘斜着飞了出去。"], ["棋罐与棋子", "两个棋罐翻倒，棋子倾泻而下。"], ["扇子", "棋盘旁一把打开的扇子也被吹飞了。"], ["仰倒的对手", "仰面倒地、瞪大眼睛的男人。"], ["笔线", "仿佛不打草稿一气呵成的有力墨线。"]]}, "zh-TW": {"title": "一個屁掀翻了棋局（畫冊選頁）", "artist": "河鍋曉齋", "date": "19世紀中後期", "place": "日本（江戶—明治時代）", "game": "圍棋", "medium": "折頁畫冊（26個對開頁）之一；紙本墨筆淡彩", "size": "畫冊（合起）28×18公分", "credit": "安妮與安東尼·多費捐贈（紀念埃文·特納）", "p": ["這是活躍於幕末至明治的畫家河鍋曉齋（1831—1889年）畫冊中的一頁，用迅疾奔放的墨線畫在折頁畫冊上。曉齋受過狩野派嚴格的訓練，同時以妖怪畫、戲畫和諷刺畫廣受歡迎。", "美術館的標題就說明了一切：「一個屁掀翻了棋局」。左邊戴烏帽子的男人彎下腰，右邊的棋盤飛上半空，棋罐裡的棋子如雨灑落，對手仰面跌倒。認真的對局被一下子毀掉——曉齋用他飛快的筆，畫出了日本自古畫卷中就有的「屁」的笑料。"], "spots": [["戴烏帽子的男人", "彎腰撅臀的男人，大概就是禍首。"], ["飛起的棋盤", "畫著格子的棋盤斜著飛了出去。"], ["棋罐與棋子", "兩個棋罐翻倒，棋子傾瀉而下。"], ["扇子", "棋盤旁一把打開的扇子也被吹飛了。"], ["仰倒的對手", "仰面倒地、瞪大眼睛的男人。"], ["筆線", "彷彿不打草稿一氣呵成的有力墨線。"]]}, "ko": {"title": "방귀가 바둑판을 뒤엎다(화첩 중에서)", "artist": "가와나베 교사이", "date": "1800년대 중후반", "place": "일본(에도~메이지 시대)", "game": "바둑", "medium": "26면 접이식 화첩 중 한 장면. 종이에 수묵담채", "size": "화첩(접은 상태) 28×18cm", "credit": "앤·앤서니 도페이 기증(에번 터너를 기리며)", "p": ["막부 말기부터 메이지 시대에 걸쳐 활약한 화가 가와나베 교사이(1831~1889년)의 화첩 한 장면으로, 접이식 화첩에 붓 가는 대로 빠르게 그은 먹선으로 그렸습니다. 교사이는 가노파의 탄탄한 기량을 갖추고도 요괴 그림, 희화, 풍자화로 인기를 모았습니다.", "미술관이 붙인 제목이 모든 것을 말해 줍니다. ‘방귀가 바둑판을 뒤엎다’. 왼쪽의 에보시 쓴 남자가 몸을 숙인 끝에, 오른쪽에서는 바둑판이 공중에 날고 바둑통에서 돌이 비처럼 쏟아지며 상대 남자는 벌러덩 넘어졌습니다. 진지한 대국을 단 한 방에 망쳐 버리는 우스꽝스러움. 옛 두루마리 그림에도 나오는 ‘방귀’ 웃음을 교사이다운 빠른 붓으로 그렸습니다."], "spots": [["에보시를 쓴 남자", "몸을 숙여 엉덩이를 내민 남자. 소동의 원인일까요?"], ["날아가는 바둑판", "줄이 그어진 바둑판이 비스듬히 날아갑니다."], ["바둑통과 돌", "바둑통 두 개가 뒤집혀 돌이 쏟아집니다."], ["부채", "바둑판 곁에서 펼친 부채도 날아갑니다."], ["넘어진 상대", "벌러덩 넘어져 눈을 휘둥그레 뜬 남자."], ["붓의 선", "밑그림 없이 단숨에 그은 듯한 힘찬 먹선."]]}, "es": {"title": "Un pedo arruina una partida de go (de un álbum de bocetos)", "artist": "Kawanabe Kyōsai", "date": "Mediados o finales del siglo XIX", "place": "Japón (periodos Edo a Meiji)", "game": "Go", "medium": "Una doble página de un álbum plegable de 26 dobles hojas; tinta y color sobre papel", "size": "Álbum (cerrado) 28 × 18 cm", "credit": "Donación de Anne y Anthony d’Offay en honor de Evan Turner", "p": ["Una escena de un álbum de bocetos de Kawanabe Kyōsai (1831–1889), pintor activo desde el final del shogunato hasta la era Meiji, dibujada con trazos rápidos y libres en las páginas de un álbum plegable. Formado en la exigente técnica de la escuela Kanō, Kyōsai fue también muy querido por sus demonios, caricaturas y sátiras.", "El título del museo lo dice todo: «Un pedo arruina una partida de go». A la izquierda, un hombre con gorro negro se agacha; a la derecha, el tablero sale volando, los cuencos dejan caer una lluvia de piedras y su rival cae de espaldas. Una partida seria arruinada de un solo golpe: Kyōsai recoge con su pincel veloz el viejo humor japonés del pedo, presente ya en rollos medievales."], "spots": [["El hombre del gorro negro", "Agachado, con el trasero hacia fuera: ¿el causante del lío?"], ["El tablero volando", "El tablero cuadriculado sale despedido en diagonal."], ["Cuencos y piedras", "Dos cuencos se vuelcan y las piedras caen como lluvia."], ["El abanico", "Un abanico abierto sale volando junto al tablero."], ["El rival derribado", "Tumbado de espaldas, con los ojos muy abiertos."], ["El trazo", "Líneas de tinta enérgicas, como hechas de una vez sin boceto."]]}, "fr": {"title": "Un pet renverse une partie de go (d’un album de croquis)", "artist": "Kawanabe Kyōsai", "date": "Milieu à fin du XIXe siècle", "place": "Japon (époques d’Edo à Meiji)", "game": "Go", "medium": "Une double page d’un album en accordéon de 26 doubles feuillets ; encre et couleurs sur papier", "size": "Album (fermé) 28 × 18 cm", "credit": "Don d’Anne et Anthony d’Offay en l’honneur d’Evan Turner", "p": ["Une scène d’un album de croquis de Kawanabe Kyōsai (1831–1889), peintre actif de la fin du shogunat à l’ère Meiji, tracée à traits rapides et libres sur les pages d’un album en accordéon. Formé à la technique exigeante de l’école Kanō, Kyōsai était aussi adoré pour ses démons, caricatures et satires.", "Le titre du musée dit tout : « Un pet renverse une partie de go ». À gauche, un homme coiffé d’un bonnet noir se penche ; à droite, le goban s’envole, les bols déversent une pluie de pierres et l’adversaire tombe à la renverse. Une partie sérieuse ruinée d’un seul coup : Kyōsai reprend, de son pinceau rapide, le vieil humour japonais du pet, déjà présent dans des rouleaux médiévaux."], "spots": [["L’homme au bonnet noir", "Penché, le derrière en avant : la cause du désastre ?"], ["Le goban qui s’envole", "Le plateau quadrillé part de travers."], ["Bols et pierres", "Deux bols se renversent et les pierres pleuvent."], ["L’éventail", "Un éventail ouvert s’envole près du plateau."], ["L’adversaire renversé", "Sur le dos, les yeux écarquillés."], ["Le trait", "Des traits d’encre énergiques, comme tracés d’un jet sans esquisse."]]}, "pt": {"title": "Um pum estraga uma partida de go (de um álbum de esboços)", "artist": "Kawanabe Kyōsai", "date": "Meados a finais do século XIX", "place": "Japão (períodos Edo a Meiji)", "game": "Go", "medium": "Uma dupla página de um álbum em acordeão de 26 folhas duplas; tinta e cor sobre papel", "size": "Álbum (fechado) 28 × 18 cm", "credit": "Doação de Anne e Anthony d’Offay em honra de Evan Turner", "p": ["Uma cena de um álbum de esboços de Kawanabe Kyōsai (1831–1889), pintor ativo do fim do xogunato à era Meiji, desenhada com traços rápidos e livres nas páginas de um álbum em acordeão. Formado na técnica exigente da escola Kanō, Kyōsai era também adorado pelos seus demónios, caricaturas e sátiras.", "O título do museu diz tudo: «Um pum estraga uma partida de go». À esquerda, um homem de barrete preto dobra-se; à direita, o tabuleiro voa, as taças despejam uma chuva de pedras e o adversário cai de costas. Uma partida séria arruinada de um só golpe: Kyōsai regista com o seu pincel veloz o velho humor japonês do pum, já presente em rolos medievais."], "spots": [["O homem de barrete preto", "Dobrado, com o traseiro de fora — o causador da confusão?"], ["O tabuleiro a voar", "O tabuleiro quadriculado sai disparado na diagonal."], ["Taças e pedras", "Duas taças viram-se e as pedras caem como chuva."], ["O leque", "Um leque aberto voa junto ao tabuleiro."], ["O adversário derrubado", "Caído de costas, de olhos arregalados."], ["O traço", "Linhas de tinta enérgicas, como feitas de uma vez sem esboço."]]}, "de": {"title": "Ein Furz wirft eine Go-Partie um (aus einem Skizzenalbum)", "artist": "Kawanabe Kyōsai", "date": "Mitte bis Ende 19. Jahrhundert", "place": "Japan (Edo- bis Meiji-Zeit)", "game": "Go", "medium": "Eine Doppelseite eines Leporello-Albums mit 26 Doppelblättern; Tusche und Farben auf Papier", "size": "Album (geschlossen) 28 × 18 cm", "credit": "Geschenk von Anne und Anthony d’Offay zu Ehren von Evan Turner", "p": ["Eine Szene aus einem Skizzenalbum von Kawanabe Kyōsai (1831–1889), einem Maler vom Ende der Shogunatszeit bis in die Meiji-Ära, mit schnellen, freien Pinselstrichen auf die Seiten eines Faltalbums gesetzt. In der strengen Technik der Kanō-Schule ausgebildet, war Kyōsai auch für Dämonen, Karikaturen und Satiren beliebt.", "Der Titel des Museums sagt alles: „Ein Furz wirft eine Go-Partie um“. Links beugt sich ein Mann mit schwarzer Kappe vor; rechts fliegt das Brett durch die Luft, die Steindosen lassen Steine regnen, und der Gegner fällt rücklings um. Eine ernste Partie, mit einem Knall ruiniert – Kyōsai hält mit flinkem Pinsel den alten japanischen Furzhumor fest, den schon mittelalterliche Bildrollen kennen."], "spots": [["Der Mann mit schwarzer Kappe", "Vorgebeugt, das Hinterteil herausgestreckt – der Verursacher?"], ["Das fliegende Brett", "Das linierte Go-Brett fliegt schräg davon."], ["Dosen und Steine", "Zwei Steindosen kippen, die Steine prasseln herab."], ["Der Fächer", "Ein offener Fächer fliegt neben dem Brett davon."], ["Der umgeworfene Gegner", "Auf dem Rücken, mit weit aufgerissenen Augen."], ["Die Pinselführung", "Kräftige Tuschelinien, wie in einem Zug ohne Vorzeichnung."]]}, "ru": {"title": "Пук опрокидывает партию в го (из альбома набросков)", "artist": "Каванабэ Кёсай", "date": "Середина — конец XIX века", "place": "Япония (периоды Эдо — Мэйдзи)", "game": "Го", "medium": "Разворот альбома-гармошки из 26 двойных листов; тушь и краски на бумаге", "size": "Альбом (в сложенном виде) 28 × 18 см", "credit": "Дар Энн и Энтони д’Оффэй в честь Эвана Тёрнера", "p": ["Сцена из альбома набросков Каванабэ Кёсая (1831–1889) — художника, работавшего с конца сёгуната до эпохи Мэйдзи, — быстрыми свободными мазками на страницах складного альбома. Выученик строгой школы Кано, Кёсай был любим и за демонов, карикатуры и сатиру.", "Название музея говорит само за себя: «Пук опрокидывает партию в го». Слева мужчина в чёрной шапке нагнулся; справа доска летит по воздуху, из чаш дождём сыплются камни, а соперник падает навзничь. Серьёзная партия погублена одним залпом: Кёсай быстрой кистью продолжает старую японскую традицию юмора о пуках, известную ещё по средневековым свиткам."], "spots": [["Мужчина в чёрной шапке", "Нагнулся, выставив зад, — виновник переполоха?"], ["Летящая доска", "Расчерченная доска го улетает наискось."], ["Чаши и камни", "Две чаши опрокидываются, и камни сыплются вниз."], ["Веер", "Раскрытый веер тоже уносит рядом с доской."], ["Опрокинутый соперник", "Лежит на спине, широко раскрыв глаза."], ["Линия кисти", "Энергичные линии туши, словно проведённые разом, без наброска."]]}, "tr": {"title": "Bir yellenme go oyununu altüst ediyor (bir eskiz albümünden)", "artist": "Kawanabe Kyōsai", "date": "19. yüzyılın ortası–sonu", "place": "Japonya (Edo–Meiji dönemi)", "game": "Go", "medium": "26 çift yapraklı akordeon albümün bir açılımı; kâğıt üzerine mürekkep ve renk", "size": "Albüm (kapalı) 28 × 18 cm", "credit": "Anne ve Anthony d’Offay bağışı, Evan Turner onuruna", "p": ["Şogunluğun son yıllarından Meiji dönemine kadar çalışmış ressam Kawanabe Kyōsai’nin (1831–1889) eskiz albümünden bir sahne; katlanır bir albümün sayfalarına hızlı, serbest fırça darbeleriyle çizilmiş. Kanō okulunun titiz tekniğiyle yetişen Kyōsai, cinleri, karikatürleri ve hicivleriyle de sevilirdi.", "Müzenin verdiği ad her şeyi anlatıyor: “Bir yellenme go oyununu altüst ediyor.” Solda siyah başlıklı bir adam eğiliyor; sağda tahta havaya uçuyor, kaplardan taşlar yağmur gibi dökülüyor, rakip sırtüstü devriliyor. Ciddi bir oyun tek bir patlamayla mahvoluyor: Kyōsai, ortaçağ tomarlarında bile görülen eski Japon yellenme mizahını hızlı fırçasıyla resmediyor."], "spots": [["Siyah başlıklı adam", "Eğilmiş, kalçasını çıkarmış — kargaşanın sebebi mi?"], ["Uçan tahta", "Çizgili go tahtası çapraz uçup gidiyor."], ["Kaplar ve taşlar", "İki kap devriliyor, taşlar yağıyor."], ["Yelpaze", "Tahtanın yanında açık bir yelpaze de uçuyor."], ["Devrilen rakip", "Sırtüstü yatmış, gözleri faltaşı gibi açık."], ["Fırça çizgisi", "Taslaksız, bir çırpıda çekilmiş gibi güçlü mürekkep çizgileri."]]}, "id": {"title": "Kentut Mengacaukan Permainan Go (dari album sketsa)", "artist": "Kawanabe Kyōsai", "date": "Pertengahan–akhir abad ke-19", "place": "Jepang (zaman Edo–Meiji)", "game": "Go", "medium": "Satu bukaan dari album lipat 26 lembar ganda; tinta dan warna di atas kertas", "size": "Album (tertutup) 28 × 18 cm", "credit": "Hibah Anne dan Anthony d’Offay untuk menghormati Evan Turner", "p": ["Satu adegan dari album sketsa Kawanabe Kyōsai (1831–1889), pelukis yang aktif dari akhir keshogunan hingga era Meiji, digambar dengan sapuan kuas cepat dan bebas di halaman album lipat. Terlatih dalam teknik ketat aliran Kanō, Kyōsai juga digemari karena gambar setan, karikatur, dan satirenya.", "Judul dari museum sudah menjelaskan semuanya: “Kentut Mengacaukan Permainan Go.” Di kiri seorang pria bertopi hitam membungkuk; di kanan papan go terbang, mangkuk menumpahkan hujan batu, dan lawannya jatuh terlentang. Permainan serius hancur dalam satu letupan — Kyōsai merekam dengan kuasnya yang cepat humor kentut Jepang kuno yang sudah ada dalam gulungan abad pertengahan."], "spots": [["Pria bertopi hitam", "Membungkuk dengan pantat menonjol — biang keributan?"], ["Papan yang terbang", "Papan go bergaris melayang miring."], ["Mangkuk dan batu", "Dua mangkuk terguling, batu-batunya berhamburan."], ["Kipas", "Kipas terbuka ikut terbang di dekat papan."], ["Lawan yang terjungkal", "Terlentang dengan mata terbelalak."], ["Sapuan kuas", "Garis tinta yang kuat, seakan dibuat sekali jadi tanpa sketsa."]]}, "hi": {"title": "पाद से उलटा गो का खेल (रेखाचित्र एल्बम से)", "artist": "कावानाबे क्योसाई", "date": "1800 के दशक का मध्य से अंत", "place": "जापान (एदो से मेइजी काल)", "game": "गो", "medium": "26 दोहरे पन्नों वाले तह-एल्बम का एक खुला पन्ना; काग़ज़ पर स्याही और रंग", "size": "एल्बम (बंद) 28 × 18 सेमी", "credit": "ऐन और एंथनी डॉफ़े का उपहार, इवान टर्नर के सम्मान में", "p": ["शोगुनशाही के अंतिम वर्षों से मेइजी युग तक सक्रिय चित्रकार कावानाबे क्योसाई (1831–1889) के रेखाचित्र एल्बम का एक दृश्य, तह वाले एल्बम के पन्नों पर तेज़, खुले ब्रश-स्ट्रोकों से बना। कानो शैली की कड़ी तकनीक में प्रशिक्षित क्योसाई अपने भूत-प्रेतों, व्यंग्य-चित्रों और कटाक्षों के लिए भी लोकप्रिय थे।", "संग्रहालय का शीर्षक सब कह देता है: ‘पाद से उलटा गो का खेल’। बाईं ओर काली टोपी वाला आदमी झुकता है; दाईं ओर बिसात हवा में उड़ती है, कटोरों से पत्थरों की बारिश होती है और प्रतिद्वंद्वी पीठ के बल गिर पड़ता है। एक गंभीर बाज़ी एक ही धमाके में बर्बाद — क्योसाई अपने तेज़ ब्रश से पाद के उस पुराने जापानी हास्य को दर्ज करते हैं जो मध्यकालीन चित्र-पटों में भी मिलता है।"], "spots": [["काली टोपी वाला आदमी", "झुका हुआ, पीछा बाहर निकाले — हंगामे की वजह?"], ["उड़ती बिसात", "रेखाओं वाली गो की बिसात तिरछी उड़ जाती है।"], ["कटोरे और पत्थर", "दो कटोरे उलटते हैं और पत्थर बरसते हैं।"], ["पंखा", "बिसात के पास एक खुला पंखा भी उड़ता है।"], ["गिरा हुआ प्रतिद्वंद्वी", "पीठ के बल पड़ा, आँखें फटी हुई।"], ["ब्रश की रेखा", "बिना ख़ाके के एक ही झटके में खिंची-सी दमदार स्याही की रेखाएँ।"]]}, "ar": {"title": "ضرطة تقلب دور الغو (من ألبوم رسوم)", "artist": "كاوانابي كيوساي", "date": "منتصف القرن التاسع عشر إلى أواخره", "place": "اليابان (من عصر إيدو إلى ميجي)", "game": "الغو", "medium": "صفحة مزدوجة من ألبوم مطوي من 26 ورقة مزدوجة؛ حبر وألوان على ورق", "size": "الألبوم (مغلقًا) 28 × 18 سم", "credit": "هدية آن وأنتوني دوفاي تكريمًا لإيفان تيرنر", "p": ["مشهد من ألبوم رسوم لكاوانابي كيوساي (1831–1889)، رسام نشط من أواخر عهد الشوغونات إلى عصر ميجي، رُسم بضربات فرشاة سريعة حرة على صفحات ألبوم مطوي. تدرّب كيوساي على تقنية مدرسة كانو الصارمة، وأحبّه الناس أيضًا لرسومه للشياطين وكاريكاتيراته وسخريته.", "عنوان المتحف يقول كل شيء: «ضرطة تقلب دور الغو». على اليسار رجل بقلنسوة سوداء ينحني، وعلى اليمين تطير الرقعة في الهواء، وتنثر الأوعية مطرًا من الأحجار، وينقلب الخصم على ظهره. دور جادّ يفسد بضربة واحدة: يسجّل كيوساي بفرشاته السريعة دعابة الضرطة اليابانية القديمة التي عرفتها اللفائف المصوّرة منذ العصور الوسطى."], "spots": [["صاحب القلنسوة السوداء", "منحنٍ يُبرز مؤخرته — سبب الفوضى؟"], ["الرقعة الطائرة", "رقعة الغو المخططة تطير مائلة."], ["الأوعية والأحجار", "وعاءان ينقلبان والأحجار تتساقط."], ["المروحة", "مروحة مفتوحة تطير أيضًا قرب الرقعة."], ["الخصم المقلوب", "ملقى على ظهره، عيناه جاحظتان."], ["خط الفرشاة", "خطوط حبر قوية كأنها رُسمت دفعة واحدة بلا تخطيط."]]}}};
  Object.keys(A).forEach(id => Object.keys(A[id]).forEach(l => { if (T[l]) T[l][id] = A[id][l]; })); })(window.MUSEUM_PAINT_T);
/* (2026-11-24) Yokuts gambling tray for huuchuish (The Art Institute of Chicago 1994.312a-b) */
(T => { const A = {"yokuts": {"ja": {"title": "賭けの遊びの盆", "artist": "ヨクーツ族の織り手（名前不明）", "date": "1900年ごろ", "place": "アメリカ（カリフォルニア州ダンラップ近く）", "game": "フーチュイシュ（クルミのさいころ）", "medium": "植物繊維（コイル編み）", "size": "高さ5.1cm、直径61cm", "credit": "レナード・S・フロースハイム・ジュニア夫人の資金による購入", "p": ["カリフォルニアの先住民の多くは、運まかせの遊びをしていました。この盆は「フーチュイシュ」という、女性だけが遊んださいころの遊びに使われたものです。8つのクルミの殻のさいころを盆の上に投げ、点数は棒で数えました。", "盆に織り込まれた円い模様には、その遊びそのもの――さいころ、点数を数える棒、遊ぶ人たち――が表されています（美術館の解説）。遊ぶための道具に、その遊びの絵を描いた品です。写真では盆の上とまわりに、クルミの殻のさいころが置かれています。"], "spots": [["遊ぶ人たち", "ふちをめぐって並ぶ人の姿。遊びに加わる人たちです。"], ["点数の棒", "縦の短い線の束。点数を数える棒を表しています。"], ["丸い模様", "小さな丸い模様。さいころを表したものでしょうか。"], ["クルミのさいころ", "クルミの殻のさいころ。8つを盆に投げて遊びました。"], ["三角の帯", "濃い色の三角を連ねた帯。盆をぐるりと一周します。"], ["中心の輪", "中心から渦を巻く編み目と、それを囲む輪の模様。"]]}, "en": {"title": "Gambling Tray", "artist": "Yokuts weaver (name unknown)", "date": "c. 1900", "place": "United States (near Dunlap, California)", "game": "Huuchuish (walnut-shell dice)", "medium": "Plant fibers (coiled)", "size": "H. 5.1 cm, diam. 61 cm", "credit": "Purchased with funds provided by Mrs. Leonard S. Florsheim, Jr.", "p": ["Many of California’s Indigenous peoples played games of chance. This tray was used for huuchuish, a dice game played only by women: eight walnut-shell dice were thrown onto the tray, and sticks were used to keep score.", "The circular design woven into the tray shows the game itself — the dice, the score sticks and the players (the museum’s note). It is a piece of equipment that carries a picture of its own game. In the photograph, walnut-shell dice lie on and around the tray."], "spots": [["The players", "Figures circle the rim — the people who join the game."], ["Score sticks", "Bundles of short upright lines: the sticks used to keep score."], ["Round motifs", "Small round motifs — the dice, perhaps?"], ["A walnut die", "A walnut-shell die. Eight were thrown onto the tray."], ["The band of triangles", "A band of dark triangles runs all the way round."], ["The centre", "The coil spirals out from the middle, ringed by a dashed circle."]]}, "zh": {"title": "赌戏盘", "artist": "约库特人织工（姓名不详）", "date": "约1900年", "place": "美国（加利福尼亚州邓拉普附近）", "game": "胡丘伊什（核桃壳骰子）", "medium": "植物纤维（盘绕编织）", "size": "高5.1厘米，直径61厘米", "credit": "伦纳德·S·弗洛斯海姆夫人出资购藏", "p": ["加利福尼亚的许多原住民都玩碰运气的游戏。这个盘用于“胡丘伊什”，一种只有女性玩的骰子游戏：把八颗核桃壳骰子掷在盘上，用小棍计分。", "盘上编织的圆形图案表现的正是这个游戏本身——骰子、计分棍和游戏的人（美术馆解说）。这是一件把自己游戏的画面织在身上的游戏用具。照片中，核桃壳骰子放在盘上和盘的四周。"], "spots": [["游戏的人", "沿着盘边排列的人形，是参加游戏的人。"], ["计分棍", "一束束短竖线，表示计分用的小棍。"], ["圆形图案", "小小的圆形图案，也许表示骰子？"], ["核桃骰子", "核桃壳做的骰子。把八颗掷在盘上。"], ["三角带", "深色三角相连的带子，绕盘一周。"], ["中心", "编织从中心盘旋而出，外面围着一圈虚线般的环。"]]}, "zh-TW": {"title": "賭戲盤", "artist": "約庫特人織工（姓名不詳）", "date": "約1900年", "place": "美國（加利福尼亞州鄧拉普附近）", "game": "胡丘伊什（核桃殼骰子）", "medium": "植物纖維（盤繞編織）", "size": "高5.1公分，直徑61公分", "credit": "倫納德·S·弗洛斯海姆夫人出資購藏", "p": ["加利福尼亞的許多原住民都玩碰運氣的遊戲。這個盤用於「胡丘伊什」，一種只有女性玩的骰子遊戲：把八顆核桃殼骰子擲在盤上，用小棍計分。", "盤上編織的圓形圖案表現的正是這個遊戲本身——骰子、計分棍和遊戲的人（美術館解說）。這是一件把自己遊戲的畫面織在身上的遊戲用具。照片中，核桃殼骰子放在盤上和盤的四周。"], "spots": [["遊戲的人", "沿著盤邊排列的人形，是參加遊戲的人。"], ["計分棍", "一束束短豎線，表示計分用的小棍。"], ["圓形圖案", "小小的圓形圖案，也許表示骰子？"], ["核桃骰子", "核桃殼做的骰子。把八顆擲在盤上。"], ["三角帶", "深色三角相連的帶子，繞盤一周。"], ["中心", "編織從中心盤旋而出，外面圍著一圈虛線般的環。"]]}, "ko": {"title": "도박 놀이 쟁반", "artist": "요쿠츠족 직조공(이름 미상)", "date": "1900년경", "place": "미국(캘리포니아주 던랩 부근)", "game": "후추이시(호두 껍데기 주사위)", "medium": "식물 섬유(코일 짜기)", "size": "높이 5.1cm, 지름 61cm", "credit": "레너드 S. 플로샤임 주니어 부인 기금 구입", "p": ["캘리포니아의 많은 원주민은 운에 맡기는 놀이를 즐겼습니다. 이 쟁반은 여성만 하던 주사위 놀이 ‘후추이시’에 쓰였습니다. 호두 껍데기 주사위 8개를 쟁반 위에 던지고, 점수는 막대로 셌습니다.", "쟁반에 짜 넣은 둥근 무늬에는 그 놀이 자체, 곧 주사위와 점수 막대와 노는 사람들이 표현되어 있습니다(미술관 해설). 놀이 도구에 그 놀이의 그림을 담은 물건입니다. 사진에는 쟁반 위와 둘레에 호두 껍데기 주사위가 놓여 있습니다."], "spots": [["노는 사람들", "가장자리를 따라 늘어선 사람 모습. 놀이에 참여하는 사람들입니다."], ["점수 막대", "짧은 세로선 묶음. 점수를 세는 막대를 나타냅니다."], ["둥근 무늬", "작은 둥근 무늬. 주사위를 나타낸 걸까요?"], ["호두 주사위", "호두 껍데기 주사위. 8개를 쟁반에 던졌습니다."], ["삼각형 띠", "짙은 삼각형을 잇댄 띠가 한 바퀴 두릅니다."], ["가운데", "가운데서 소용돌이치는 짜임과 그것을 두른 고리 무늬."]]}, "es": {"title": "Bandeja para juegos de azar", "artist": "Tejedora yokuts (nombre desconocido)", "date": "h. 1900", "place": "Estados Unidos (cerca de Dunlap, California)", "game": "Huuchuish (dados de cáscara de nuez)", "medium": "Fibras vegetales (cestería en espiral)", "size": "Alt. 5,1 cm, diám. 61 cm", "credit": "Adquirida con fondos de la Sra. de Leonard S. Florsheim Jr.", "p": ["Muchos pueblos indígenas de California practicaban juegos de azar. Esta bandeja servía para el huuchuish, un juego de dados exclusivo de las mujeres: se lanzaban ocho dados de cáscara de nuez sobre la bandeja y se llevaba la cuenta con palitos.", "El diseño circular tejido en la bandeja muestra el propio juego: los dados, los palitos de cuenta y las jugadoras (nota del museo). Es un utensilio de juego que lleva la imagen de su propio juego. En la fotografía hay dados de cáscara de nuez sobre la bandeja y alrededor."], "spots": [["Las jugadoras", "Figuras que recorren el borde: quienes participan en el juego."], ["Palitos de cuenta", "Haces de rayitas verticales: los palitos para llevar la cuenta."], ["Motivos redondos", "Pequeños motivos redondos: ¿los dados?"], ["Un dado de nuez", "Un dado de cáscara de nuez. Se lanzaban ocho sobre la bandeja."], ["La banda de triángulos", "Una banda de triángulos oscuros da toda la vuelta."], ["El centro", "La espiral del tejido sale del centro, rodeada por un círculo de trazos."]]}, "fr": {"title": "Plateau de jeu d’argent", "artist": "Vannière yokuts (nom inconnu)", "date": "v. 1900", "place": "États-Unis (près de Dunlap, Californie)", "game": "Huuchuish (dés en coquille de noix)", "medium": "Fibres végétales (vannerie spiralée)", "size": "H. 5,1 cm, diam. 61 cm", "credit": "Achat grâce aux fonds de Mrs. Leonard S. Florsheim Jr.", "p": ["Beaucoup de peuples autochtones de Californie pratiquaient des jeux de hasard. Ce plateau servait au huuchuish, un jeu de dés réservé aux femmes : on lançait huit dés en coquille de noix sur le plateau, et l’on comptait les points avec des bâtonnets.", "Le décor circulaire tissé dans le plateau montre le jeu lui-même — les dés, les bâtonnets de marque et les joueuses (notice du musée). C’est un instrument de jeu qui porte l’image de son propre jeu. Sur la photographie, des dés en coquille de noix sont posés sur le plateau et autour."], "spots": [["Les joueuses", "Des figures font le tour du bord : celles qui prennent part au jeu."], ["Bâtonnets de marque", "Des faisceaux de petits traits verticaux : les bâtonnets pour compter."], ["Motifs ronds", "De petits motifs ronds : les dés, peut-être ?"], ["Un dé en noix", "Un dé en coquille de noix. On en lançait huit sur le plateau."], ["La bande de triangles", "Une bande de triangles sombres fait le tour."], ["Le centre", "La spirale part du centre, entourée d’un cercle en tirets."]]}, "pt": {"title": "Tabuleiro de jogos de azar", "artist": "Tecelã yokuts (nome desconhecido)", "date": "c. 1900", "place": "Estados Unidos (perto de Dunlap, Califórnia)", "game": "Huuchuish (dados de casca de noz)", "medium": "Fibras vegetais (cestaria em espiral)", "size": "Alt. 5,1 cm, diâm. 61 cm", "credit": "Adquirido com fundos da Sra. Leonard S. Florsheim Jr.", "p": ["Muitos povos indígenas da Califórnia praticavam jogos de azar. Este tabuleiro servia para o huuchuish, um jogo de dados só de mulheres: lançavam-se oito dados de casca de noz sobre o tabuleiro e contava-se com pauzinhos.", "O desenho circular tecido no tabuleiro mostra o próprio jogo — os dados, os pauzinhos de contagem e as jogadoras (nota do museu). É um utensílio de jogo que traz a imagem do seu próprio jogo. Na fotografia, há dados de casca de noz sobre o tabuleiro e à volta."], "spots": [["As jogadoras", "Figuras à volta da borda: quem participa no jogo."], ["Pauzinhos de contagem", "Feixes de tracinhos verticais: os pauzinhos para contar."], ["Motivos redondos", "Pequenos motivos redondos — os dados, talvez?"], ["Um dado de noz", "Um dado de casca de noz. Lançavam-se oito no tabuleiro."], ["A faixa de triângulos", "Uma faixa de triângulos escuros dá a volta toda."], ["O centro", "A espiral do entrançado sai do meio, rodeada por um círculo tracejado."]]}, "de": {"title": "Spieltablett für Glücksspiele", "artist": "Yokuts-Flechterin (Name unbekannt)", "date": "um 1900", "place": "USA (bei Dunlap, Kalifornien)", "game": "Huuchuish (Walnussschalen-Würfel)", "medium": "Pflanzenfasern (Spiralwulsttechnik)", "size": "H. 5,1 cm, Dm. 61 cm", "credit": "Erworben mit Mitteln von Mrs. Leonard S. Florsheim Jr.", "p": ["Viele indigene Völker Kaliforniens spielten Glücksspiele. Dieses Tablett diente dem Huuchuish, einem Würfelspiel nur für Frauen: Acht Würfel aus Walnussschalen wurden auf das Tablett geworfen, gezählt wurde mit Stäbchen.", "Das in das Tablett eingeflochtene Rundmuster zeigt das Spiel selbst – die Würfel, die Zählstäbchen und die Spielerinnen (Museumstext). Ein Spielgerät, das das Bild seines eigenen Spiels trägt. Auf dem Foto liegen Walnusswürfel auf und neben dem Tablett."], "spots": [["Die Spielerinnen", "Figuren umrunden den Rand – die Teilnehmerinnen."], ["Zählstäbchen", "Bündel kurzer senkrechter Striche: die Stäbchen zum Zählen."], ["Runde Motive", "Kleine runde Motive – vielleicht die Würfel?"], ["Ein Walnusswürfel", "Ein Würfel aus Walnussschale. Acht davon wurden geworfen."], ["Das Dreiecksband", "Ein Band dunkler Dreiecke läuft rundherum."], ["Die Mitte", "Die Wulst windet sich aus der Mitte, umgeben von einem gestrichelten Ring."]]}, "ru": {"title": "Поднос для азартной игры", "artist": "Мастерица народа йокутс (имя неизвестно)", "date": "Ок. 1900", "place": "США (близ Данлапа, Калифорния)", "game": "Хучуиш (кости из скорлупы ореха)", "medium": "Растительные волокна (спиральное плетение)", "size": "Выс. 5,1 см, диам. 61 см", "credit": "Приобретено на средства миссис Леонард С. Флоршайм-младшей", "p": ["Многие коренные народы Калифорнии играли в азартные игры. Этот поднос служил для хучуиш — игры в кости, в которую играли только женщины: на поднос бросали восемь костей из скорлупы грецкого ореха, а очки считали палочками.", "Круговой узор, вплетённый в поднос, изображает саму игру — кости, счётные палочки и игроков (пояснение музея). Это игровой предмет, несущий изображение собственной игры. На фотографии кости из скорлупы лежат на подносе и вокруг него."], "spots": [["Игроки", "Фигуры идут по кругу у края — участницы игры."], ["Счётные палочки", "Пучки коротких вертикальных черт — палочки для счёта."], ["Круглые мотивы", "Маленькие круглые мотивы — может быть, кости?"], ["Ореховая кость", "Кость из скорлупы ореха. На поднос бросали восемь."], ["Пояс треугольников", "Полоса тёмных треугольников идёт по кругу."], ["Центр", "Плетение спиралью выходит из центра, окружённое пунктирным кольцом."]]}, "tr": {"title": "Kumar Tepsisi", "artist": "Yokuts dokumacı (adı bilinmiyor)", "date": "y. 1900", "place": "ABD (Dunlap yakını, Kaliforniya)", "game": "Huuchuish (ceviz kabuğu zarlar)", "medium": "Bitki lifleri (sarmal örgü)", "size": "Yük. 5,1 cm, çap 61 cm", "credit": "Bayan Leonard S. Florsheim Jr.’ın fonuyla satın alındı", "p": ["Kaliforniya’nın pek çok yerli halkı şans oyunları oynardı. Bu tepsi, yalnızca kadınların oynadığı bir zar oyunu olan huuchuish için kullanılırdı: sekiz ceviz kabuğu zar tepsiye atılır, puanlar çubuklarla sayılırdı.", "Tepsiye dokunmuş dairesel desen oyunun kendisini gösterir — zarları, sayı çubuklarını ve oyuncuları (müze notu). Kendi oyununun resmini taşıyan bir oyun aracıdır. Fotoğrafta ceviz kabuğu zarlar tepsinin üstünde ve çevresinde duruyor."], "spots": [["Oyuncular", "Kenar boyunca dizilen figürler — oyuna katılanlar."], ["Sayı çubukları", "Kısa dikey çizgi demetleri: puan sayan çubuklar."], ["Yuvarlak motifler", "Küçük yuvarlak motifler — zarlar mı?"], ["Ceviz zar", "Ceviz kabuğundan bir zar. Sekizi tepsiye atılırdı."], ["Üçgen kuşak", "Koyu üçgenlerden bir kuşak çepeçevre dolanır."], ["Merkez", "Örgü merkezden sarmal çizerek çıkar; çevresinde kesikli bir halka var."]]}, "id": {"title": "Nampan Permainan Untung-untungan", "artist": "Penganyam Yokuts (nama tidak diketahui)", "date": "sekitar 1900", "place": "Amerika Serikat (dekat Dunlap, California)", "game": "Huuchuish (dadu kulit kenari)", "medium": "Serat tumbuhan (anyaman gulung)", "size": "Tinggi 5,1 cm, diameter 61 cm", "credit": "Dibeli dengan dana dari Ny. Leonard S. Florsheim Jr.", "p": ["Banyak masyarakat adat California memainkan permainan untung-untungan. Nampan ini dipakai untuk huuchuish, permainan dadu yang hanya dimainkan perempuan: delapan dadu kulit kenari dilempar ke nampan, dan skor dihitung dengan batang kecil.", "Motif melingkar yang dianyam di nampan menggambarkan permainan itu sendiri — dadu, batang penghitung, dan para pemainnya (catatan museum). Ini alat permainan yang membawa gambar permainannya sendiri. Di foto, dadu kulit kenari diletakkan di atas dan di sekitar nampan."], "spots": [["Para pemain", "Sosok-sosok mengitari tepi — orang yang ikut bermain."], ["Batang penghitung", "Kumpulan garis tegak pendek: batang untuk menghitung skor."], ["Motif bundar", "Motif bundar kecil — mungkin dadunya?"], ["Dadu kenari", "Dadu dari kulit kenari. Delapan dilempar ke nampan."], ["Pita segitiga", "Pita segitiga gelap melingkar penuh."], ["Pusat", "Anyaman berpilin keluar dari tengah, dikelilingi lingkaran putus-putus."]]}, "hi": {"title": "जुए के खेल की थाली", "artist": "योकुट्स बुनकर (नाम अज्ञात)", "date": "लगभग 1900", "place": "अमेरिका (डनलैप के पास, कैलिफ़ोर्निया)", "game": "हूचुइश (अख़रोट के छिलके के पासे)", "medium": "पौधों के रेशे (कुंडलित बुनाई)", "size": "ऊँचाई 5.1 सेमी, व्यास 61 सेमी", "credit": "श्रीमती लियोनार्ड एस. फ़्लोरशाइम जूनियर की निधि से ख़रीदी गई", "p": ["कैलिफ़ोर्निया के कई मूलनिवासी लोग क़िस्मत के खेल खेलते थे। यह थाली ‘हूचुइश’ के लिए थी, जो केवल स्त्रियों का पासे का खेल था: अख़रोट के छिलके के आठ पासे थाली पर फेंके जाते और अंक छड़ियों से गिने जाते।", "थाली में बुना गोल नमूना उसी खेल को दिखाता है — पासे, अंक गिनने की छड़ियाँ और खिलाड़ी (संग्रहालय की टिप्पणी)। यह ऐसा खेल-उपकरण है जो अपने ही खेल का चित्र लिए है। तस्वीर में अख़रोट के छिलके के पासे थाली पर और आसपास रखे हैं।"], "spots": [["खिलाड़ी", "किनारे के चारों ओर आकृतियाँ — खेल में भाग लेने वाले।"], ["अंक की छड़ियाँ", "छोटी खड़ी रेखाओं के गुच्छे: अंक गिनने की छड़ियाँ।"], ["गोल नमूने", "छोटे गोल नमूने — शायद पासे?"], ["अख़रोट का पासा", "अख़रोट के छिलके का पासा। आठ थाली पर फेंके जाते थे।"], ["त्रिकोणों की पट्टी", "गहरे त्रिकोणों की पट्टी पूरा चक्कर लगाती है।"], ["केंद्र", "बुनाई बीच से कुंडली बनाती निकलती है, चारों ओर टूटी रेखा का घेरा।"]]}, "ar": {"title": "صينية للعب القمار", "artist": "ناسجة من شعب يوكوتس (اسمها غير معروف)", "date": "نحو 1900", "place": "الولايات المتحدة (قرب دنلاب، كاليفورنيا)", "game": "هوتشويش (نرد من قشر الجوز)", "medium": "ألياف نباتية (نسج لولبي)", "size": "الارتفاع 5.1 سم، القطر 61 سم", "credit": "اشتُريت بتمويل من السيدة ليونارد س. فلورشايم الابن", "p": ["كانت شعوب أصلية كثيرة في كاليفورنيا تلعب ألعاب الحظ. وكانت هذه الصينية تُستعمل في «هوتشويش»، وهي لعبة نرد للنساء وحدهن: تُرمى ثمانية أحجار نرد من قشر الجوز على الصينية، وتُحسب النقاط بالعصيّ.", "النقش الدائري المنسوج في الصينية يصوّر اللعبة نفسها — النرد وعصيّ العدّ واللاعبات (شرح المتحف). إنها أداة لعب تحمل صورة لعبتها. وفي الصورة أحجار نرد من قشر الجوز على الصينية وحولها."], "spots": [["اللاعبات", "أشكال بشرية تدور حول الحافة — المشاركات في اللعب."], ["عصيّ العدّ", "حزم من خطوط عمودية قصيرة: العصيّ لعدّ النقاط."], ["زخارف مستديرة", "زخارف صغيرة مستديرة — ربما النرد؟"], ["نرد الجوز", "نرد من قشر الجوز. كانت ثمانية منها تُرمى على الصينية."], ["حزام المثلثات", "حزام من مثلثات داكنة يدور حول الصينية."], ["المركز", "يلتفّ النسج من الوسط، وتحيط به حلقة متقطعة."]]}}};
  Object.keys(A).forEach(id => Object.keys(A[id]).forEach(l => { if (T[l]) T[l][id] = A[id][l]; })); })(window.MUSEUM_PAINT_T);
