(T => { const A = {"hokkei": {"ja": {"title": "牛若丸、双六で弁慶を負かす", "artist": "魚屋北渓", "date": "1825年ごろ", "place": "日本（江戸時代）", "game": "盤双六", "medium": "摺物（色紙判の多色木版）", "size": "21.8×19.1cm", "credit": "ヘレン・C・ガンソーラス寄贈", "p": ["葛飾北斎の門人、魚屋北渓（1780〜1850年）の摺物です。摺物は、狂歌の仲間などが自分たちの歌を入れて特別に刷らせた版画で、売り物の浮世絵よりも上等な紙や金属の顔料を使い、ぜいたくに仕上げられました。", "源義経の少年時代・牛若丸と、怪力の僧兵・弁慶。2人の出会いといえば京都の五条大橋での対決が有名ですが、この摺物では勝負が盤双六に置きかえられています。牛若丸は涼しい顔で盤の向こうに座り、なぎなたを背負った弁慶は頭をかいて負けを認めています。見立ての遊びと思われます。"], "spots": [["双六盤", "箱形の双六盤。白と黒の駒が並んでいます。"], ["頭をかく弁慶", "鎧姿の弁慶が、負けて頭をかいています。"], ["牛若丸", "盤の向こうに座る、少年の牛若丸。"], ["なぎなた", "弁慶が背負う大なぎなたの刃。"], ["狂歌", "右上に書かれた歌。摺物を作らせた仲間の歌と思われます。"], ["署名", "右下の枠に北渓の署名。"]]}, "en": {"title": "Ushiwakamaru Defeats Benkei at Sugoroku", "artist": "Totoya Hokkei", "date": "c. 1825", "place": "Japan (Edo period)", "game": "Ban-sugoroku", "medium": "Surimono (color woodblock print, shikishiban)", "size": "21.8 × 19.1 cm", "credit": "Gift of Helen C. Gunsaulus", "p": ["A surimono by Totoya Hokkei (1780–1850), a pupil of Hokusai. Surimono were prints privately commissioned — often by poetry circles, with their own verses — and finished more lavishly than commercial ukiyo-e, with fine paper and metallic pigments.", "Ushiwakamaru, the boyhood name of the hero Minamoto no Yoshitsune, and the giant warrior-monk Benkei. Their famous meeting was a duel on Kyoto’s Gojō Bridge, but here the contest becomes a game of sugoroku: the boy sits calmly beyond the board while Benkei, his halberd on his back, scratches his head in defeat — a playful re-staging, it seems."], "spots": [["The sugoroku board", "A box-shaped board with white and black pieces."], ["Benkei scratching his head", "In full armour, the beaten Benkei scratches his head."], ["Ushiwakamaru", "The boy hero, seated beyond the board."], ["The halberd", "The blade of Benkei’s great naginata."], ["The poem", "Verses at upper right — probably by the circle that commissioned the print."], ["The signature", "Hokkei’s signature in the cartouche at lower right."]]}, "zh": {"title": "牛若丸以双六胜弁庆", "artist": "鱼屋北溪", "date": "约1825年", "place": "日本（江户时代）", "game": "盘双六", "medium": "摺物（色纸判套色木版）", "size": "21.8×19.1厘米", "credit": "海伦·C·冈索勒斯捐赠", "p": ["这是葛饰北斋的弟子鱼屋北溪（1780—1850年）的摺物。摺物是狂歌同好等为印上自己的诗歌而特别定制的版画，比市售浮世绘用纸更好，还用金属颜料，做工讲究。", "牛若丸是英雄源义经少年时的名字，弁庆是力大无穷的僧兵。两人最有名的相遇是京都五条大桥上的决斗，而这幅摺物把较量换成了盘双六：少年从容地坐在棋盘对面，背着长刀的弁庆挠头认输。这大概是一种“见立”的戏仿。"], "spots": [["双六盘", "箱形的双六盘，摆着白子和黑子。"], ["挠头的弁庆", "身披铠甲的弁庆输了，正在挠头。"], ["牛若丸", "坐在棋盘对面的少年牛若丸。"], ["长刀", "弁庆背着的大薙刀的刀刃。"], ["狂歌", "右上的诗句，大概是定制摺物的同好所作。"], ["署名", "右下框内北溪的署名。"]]}, "zh-TW": {"title": "牛若丸以雙六勝弁慶", "artist": "魚屋北溪", "date": "約1825年", "place": "日本（江戶時代）", "game": "盤雙六", "medium": "摺物（色紙判套色木版）", "size": "21.8×19.1公分", "credit": "海倫·C·岡索勒斯捐贈", "p": ["這是葛飾北齋的弟子魚屋北溪（1780—1850年）的摺物。摺物是狂歌同好等為印上自己的詩歌而特別訂製的版畫，比市售浮世繪用紙更好，還用金屬顏料，做工講究。", "牛若丸是英雄源義經少年時的名字，弁慶是力大無窮的僧兵。兩人最有名的相遇是京都五條大橋上的決鬥，而這幅摺物把較量換成了盤雙六：少年從容地坐在棋盤對面，背著長刀的弁慶撓頭認輸。這大概是一種「見立」的戲仿。"], "spots": [["雙六盤", "箱形的雙六盤，擺著白子和黑子。"], ["撓頭的弁慶", "身披鎧甲的弁慶輸了，正在撓頭。"], ["牛若丸", "坐在棋盤對面的少年牛若丸。"], ["長刀", "弁慶背著的大薙刀的刀刃。"], ["狂歌", "右上的詩句，大概是訂製摺物的同好所作。"], ["署名", "右下框內北溪的署名。"]]}, "ko": {"title": "우시와카마루, 쌍륙으로 벤케이를 이기다", "artist": "도토야 홋케이", "date": "1825년경", "place": "일본(에도 시대)", "game": "반스고로쿠(쌍륙)", "medium": "스리모노(시키시판 다색 목판)", "size": "21.8×19.1cm", "credit": "헬렌 C. 건솔러스 기증", "p": ["가쓰시카 호쿠사이의 제자 도토야 홋케이(1780~1850년)의 스리모노입니다. 스리모노는 교카 동호회 등이 자신들의 노래를 넣어 특별히 찍게 한 판화로, 시판 우키요에보다 좋은 종이와 금속 안료를 써서 호화롭게 만들었습니다.", "영웅 미나모토노 요시쓰네의 어린 시절 이름 우시와카마루와 괴력의 승병 벤케이. 두 사람의 만남이라면 교토 고조 대교의 대결이 유명하지만, 이 스리모노에서는 승부가 쌍륙으로 바뀌었습니다. 소년은 태연히 판 너머에 앉아 있고, 나기나타를 멘 벤케이는 머리를 긁으며 패배를 인정합니다. 비틀어 보는 ‘미타테’ 놀이로 보입니다."], "spots": [["쌍륙판", "상자 모양의 쌍륙판. 흰 말과 검은 말이 놓여 있습니다."], ["머리를 긁는 벤케이", "갑옷 차림의 벤케이가 져서 머리를 긁습니다."], ["우시와카마루", "판 너머에 앉은 소년 우시와카마루."], ["나기나타", "벤케이가 멘 큰 나기나타의 날."], ["교카", "오른쪽 위의 노래. 스리모노를 주문한 동호회의 노래로 보입니다."], ["서명", "오른쪽 아래 틀 안의 홋케이 서명."]]}, "es": {"title": "Ushiwakamaru vence a Benkei al sugoroku", "artist": "Totoya Hokkei", "date": "h. 1825", "place": "Japón (periodo Edo)", "game": "Ban-sugoroku", "medium": "Surimono (xilografía en color, shikishiban)", "size": "21,8 × 19,1 cm", "credit": "Donación de Helen C. Gunsaulus", "p": ["Un surimono de Totoya Hokkei (1780–1850), discípulo de Hokusai. Los surimono eran estampas de encargo privado —a menudo de círculos de poesía, con sus propios versos— y se acababan con más lujo que el ukiyo-e comercial, con buen papel y pigmentos metálicos.", "Ushiwakamaru, nombre de niñez del héroe Minamoto no Yoshitsune, y el gigantesco monje guerrero Benkei. Su famoso encuentro fue un duelo en el puente Gojō de Kioto, pero aquí el combate se convierte en una partida de sugoroku: el muchacho se sienta tranquilo tras el tablero y Benkei, con la alabarda a la espalda, se rasca la cabeza derrotado. Parece una recreación juguetona."], "spots": [["El tablero de sugoroku", "Un tablero en forma de caja con piezas blancas y negras."], ["Benkei rascándose la cabeza", "Con armadura completa, el vencido se rasca la cabeza."], ["Ushiwakamaru", "El joven héroe, sentado tras el tablero."], ["La alabarda", "La hoja de la gran naginata de Benkei."], ["El poema", "Versos arriba a la derecha, probablemente del círculo que encargó la estampa."], ["La firma", "La firma de Hokkei en la cartela de abajo a la derecha."]]}, "fr": {"title": "Ushiwakamaru bat Benkei au sugoroku", "artist": "Totoya Hokkei", "date": "v. 1825", "place": "Japon (époque d’Edo)", "game": "Ban-sugoroku", "medium": "Surimono (estampe en couleurs, shikishiban)", "size": "21,8 × 19,1 cm", "credit": "Don d’Helen C. Gunsaulus", "p": ["Un surimono de Totoya Hokkei (1780–1850), élève d’Hokusai. Les surimono étaient des estampes de commande privée — souvent par des cercles de poésie, avec leurs propres vers — plus luxueuses que l’ukiyo-e du commerce, avec beau papier et pigments métalliques.", "Ushiwakamaru, nom d’enfance du héros Minamoto no Yoshitsune, et le gigantesque moine-guerrier Benkei. Leur célèbre rencontre fut un duel sur le pont Gojō de Kyoto, mais ici l’affrontement devient une partie de sugoroku : l’enfant est assis, serein, derrière le plateau, et Benkei, la hallebarde au dos, se gratte la tête, vaincu. Une transposition ludique, semble-t-il."], "spots": [["Le plateau de sugoroku", "Un plateau en forme de boîte, avec des pions blancs et noirs."], ["Benkei se grattant la tête", "En armure, le vaincu se gratte la tête."], ["Ushiwakamaru", "Le jeune héros, assis derrière le plateau."], ["La hallebarde", "La lame de la grande naginata de Benkei."], ["Le poème", "Des vers en haut à droite, sans doute du cercle qui commanda l’estampe."], ["La signature", "La signature de Hokkei dans le cartouche en bas à droite."]]}, "pt": {"title": "Ushiwakamaru vence Benkei no sugoroku", "artist": "Totoya Hokkei", "date": "c. 1825", "place": "Japão (período Edo)", "game": "Ban-sugoroku", "medium": "Surimono (xilogravura a cores, shikishiban)", "size": "21,8 × 19,1 cm", "credit": "Doação de Helen C. Gunsaulus", "p": ["Um surimono de Totoya Hokkei (1780–1850), discípulo de Hokusai. Os surimono eram gravuras de encomenda privada — muitas vezes de círculos de poesia, com os seus próprios versos — e acabadas com mais luxo do que o ukiyo-e comercial, com bom papel e pigmentos metálicos.", "Ushiwakamaru, nome de infância do herói Minamoto no Yoshitsune, e o gigantesco monge guerreiro Benkei. O seu famoso encontro foi um duelo na ponte Gojō de Quioto, mas aqui o combate torna-se uma partida de sugoroku: o rapaz senta-se tranquilo atrás do tabuleiro e Benkei, de alabarda às costas, coça a cabeça derrotado. Parece uma recriação brincalhona."], "spots": [["O tabuleiro de sugoroku", "Um tabuleiro em forma de caixa com peças brancas e pretas."], ["Benkei a coçar a cabeça", "De armadura completa, o vencido coça a cabeça."], ["Ushiwakamaru", "O jovem herói, sentado atrás do tabuleiro."], ["A alabarda", "A lâmina da grande naginata de Benkei."], ["O poema", "Versos em cima à direita, provavelmente do círculo que encomendou a gravura."], ["A assinatura", "A assinatura de Hokkei na cartela em baixo à direita."]]}, "de": {"title": "Ushiwakamaru besiegt Benkei beim Sugoroku", "artist": "Totoya Hokkei", "date": "um 1825", "place": "Japan (Edo-Zeit)", "game": "Ban-Sugoroku", "medium": "Surimono (Farbholzschnitt, Shikishiban)", "size": "21,8 × 19,1 cm", "credit": "Geschenk von Helen C. Gunsaulus", "p": ["Ein Surimono von Totoya Hokkei (1780–1850), einem Schüler Hokusais. Surimono waren privat in Auftrag gegebene Drucke – oft von Dichterkreisen, mit eigenen Versen – und aufwendiger gefertigt als kommerzielle Ukiyo-e, mit feinem Papier und Metallpigmenten.", "Ushiwakamaru, der Kindername des Helden Minamoto no Yoshitsune, und der riesige Kriegermönch Benkei. Berühmt ist ihr Duell auf der Gojō-Brücke in Kyoto, doch hier wird der Kampf zur Sugoroku-Partie: Der Junge sitzt gelassen hinter dem Brett, Benkei mit der Hellebarde auf dem Rücken kratzt sich geschlagen am Kopf – wohl eine spielerische Umdeutung."], "spots": [["Das Sugoroku-Brett", "Ein kastenförmiges Brett mit weißen und schwarzen Steinen."], ["Benkei kratzt sich am Kopf", "In voller Rüstung kratzt sich der Besiegte am Kopf."], ["Ushiwakamaru", "Der junge Held, hinter dem Brett sitzend."], ["Die Hellebarde", "Die Klinge von Benkeis großer Naginata."], ["Das Gedicht", "Verse oben rechts – wohl von dem Kreis, der den Druck bestellte."], ["Die Signatur", "Hokkeis Signatur in der Kartusche unten rechts."]]}, "ru": {"title": "Усивакамару обыгрывает Бэнкэя в сугороку", "artist": "Тотоя Хоккэй", "date": "Ок. 1825", "place": "Япония (период Эдо)", "game": "Бан-сугороку", "medium": "Суримоно (цветная ксилография, сикисибан)", "size": "21,8 × 19,1 см", "credit": "Дар Хелен К. Гансолус", "p": ["Суримоно Тотоя Хоккэя (1780–1850), ученика Хокусая. Суримоно заказывали частным образом — часто поэтические кружки, со своими стихами, — и печатали роскошнее, чем коммерческие укиё-э: на хорошей бумаге, с металлическими пигментами.", "Усивакамару — детское имя героя Минамото-но Ёсицунэ — и великан-монах Бэнкэй. Их знаменитая встреча — поединок на мосту Годзё в Киото, но здесь схватка превращается в партию сугороку: мальчик спокойно сидит за доской, а Бэнкэй с алебардой за спиной чешет затылок, признавая поражение. Похоже, это шутливое переосмысление."], "spots": [["Доска сугороку", "Доска-ящик с белыми и чёрными шашками."], ["Бэнкэй чешет затылок", "В полном доспехе побеждённый чешет затылок."], ["Усивакамару", "Юный герой сидит за доской."], ["Алебарда", "Лезвие большой нагинаты Бэнкэя."], ["Стихи", "Стихи вверху справа — вероятно, кружка, заказавшего гравюру."], ["Подпись", "Подпись Хоккэя в картуше внизу справа."]]}, "tr": {"title": "Ushiwakamaru, Benkei’yi sugoroku’da yeniyor", "artist": "Totoya Hokkei", "date": "y. 1825", "place": "Japonya (Edo dönemi)", "game": "Ban-sugoroku", "medium": "Surimono (renkli ağaç baskı, shikishiban)", "size": "21,8 × 19,1 cm", "credit": "Helen C. Gunsaulus bağışı", "p": ["Hokusai’nin öğrencisi Totoya Hokkei’nin (1780–1850) bir surimonosu. Surimonolar özel olarak — çoğu zaman şiir çevrelerince, kendi dizeleriyle — sipariş edilen ve ticari ukiyo-e’den daha gösterişli, iyi kâğıt ve metalik pigmentlerle basılan baskılardı.", "Kahraman Minamoto no Yoshitsune’nin çocukluk adı Ushiwakamaru ile dev savaşçı keşiş Benkei. Ünlü karşılaşmaları Kyoto’daki Gojō Köprüsü’ndeki düellodur; burada ise mücadele bir sugoroku oyununa dönüşüyor: çocuk tahtanın ardında sakin oturuyor, sırtında teber taşıyan Benkei yenilgiyle başını kaşıyor. Oyunbaz bir yeniden yorum gibi görünüyor."], "spots": [["Sugoroku tahtası", "Beyaz ve siyah taşlı, kutu biçimli bir tahta."], ["Başını kaşıyan Benkei", "Tam zırhlı, yenilen Benkei başını kaşıyor."], ["Ushiwakamaru", "Tahtanın ardında oturan genç kahraman."], ["Teber", "Benkei’nin büyük naginatasının ağzı."], ["Şiir", "Sağ üstteki dizeler — büyük olasılıkla baskıyı sipariş eden çevreden."], ["İmza", "Sağ alttaki çerçevede Hokkei’nin imzası."]]}, "id": {"title": "Ushiwakamaru Mengalahkan Benkei dalam Sugoroku", "artist": "Totoya Hokkei", "date": "sekitar 1825", "place": "Jepang (zaman Edo)", "game": "Ban-sugoroku", "medium": "Surimono (cetak balok kayu berwarna, shikishiban)", "size": "21,8 × 19,1 cm", "credit": "Hibah Helen C. Gunsaulus", "p": ["Sebuah surimono karya Totoya Hokkei (1780–1850), murid Hokusai. Surimono adalah cetakan pesanan pribadi — sering oleh kelompok puisi, dengan sajak mereka sendiri — dan dibuat lebih mewah daripada ukiyo-e komersial, dengan kertas bagus dan pigmen logam.", "Ushiwakamaru, nama kecil pahlawan Minamoto no Yoshitsune, dan biksu prajurit raksasa Benkei. Pertemuan mereka yang terkenal adalah duel di Jembatan Gojō di Kyoto, tetapi di sini pertarungan menjadi permainan sugoroku: si anak duduk tenang di balik papan, sementara Benkei dengan tombak di punggung menggaruk kepala karena kalah. Tampaknya ini gubahan yang jenaka."], "spots": [["Papan sugoroku", "Papan berbentuk kotak dengan bidak putih dan hitam."], ["Benkei menggaruk kepala", "Berbaju zirah lengkap, yang kalah menggaruk kepala."], ["Ushiwakamaru", "Sang pahlawan muda, duduk di balik papan."], ["Tombak", "Mata naginata besar milik Benkei."], ["Sajak", "Sajak di kanan atas — mungkin dari kelompok yang memesan cetakan ini."], ["Tanda tangan", "Tanda tangan Hokkei di bingkai kanan bawah."]]}, "hi": {"title": "उशिवाकामारु ने सुगोरोकु में बेनकेई को हराया", "artist": "तोतोया होक्केई", "date": "लगभग 1825", "place": "जापान (एदो काल)", "game": "बान-सुगोरोकु", "medium": "सुरिमोनो (रंगीन काष्ठ-छापा, शिकिशिबान)", "size": "21.8 × 19.1 सेमी", "credit": "हेलेन सी. गनसॉलस का उपहार", "p": ["होकुसाई के शिष्य तोतोया होक्केई (1780–1850) का एक सुरिमोनो। सुरिमोनो निजी तौर पर बनवाए गए छापे होते थे — अक्सर कविता-मंडलियाँ अपनी कविताओं के साथ बनवाती थीं — और ये बाज़ारू उकियो-ए से ज़्यादा शानदार, बढ़िया काग़ज़ और धात्विक रंगों से बनते थे।", "उशिवाकामारु — नायक मिनामोतो नो योशित्सुने का बचपन का नाम — और विशालकाय योद्धा-भिक्षु बेनकेई। उनकी प्रसिद्ध भेंट क्योतो के गोजो पुल पर द्वंद्व थी, पर यहाँ मुक़ाबला सुगोरोकु की बाज़ी बन गया है: लड़का बिसात के उस पार शांत बैठा है, और पीठ पर भाला लिए बेनकेई हारकर सिर खुजा रहा है। यह एक चंचल रूपांतर लगता है।"], "spots": [["सुगोरोकु बिसात", "सफ़ेद और काली गोटियों वाली संदूक जैसी बिसात।"], ["सिर खुजाता बेनकेई", "पूरे कवच में हारा हुआ बेनकेई सिर खुजाता है।"], ["उशिवाकामारु", "बिसात के उस पार बैठा युवा नायक।"], ["भाला", "बेनकेई के बड़े नागिनाता का फल।"], ["कविता", "ऊपर दाईं ओर की पंक्तियाँ — शायद छापा बनवाने वाली मंडली की।"], ["हस्ताक्षर", "नीचे दाईं ओर के खाने में होक्केई के हस्ताक्षर।"]]}, "ar": {"title": "أوشيواكامارو يهزم بنكي في السوغوروكو", "artist": "توتويا هوكّي", "date": "نحو 1825", "place": "اليابان (عصر إيدو)", "game": "بان-سوغوروكو", "medium": "سوريمونو (طباعة خشبية ملوّنة، قطع شيكيشيبان)", "size": "21.8 × 19.1 سم", "credit": "هدية هيلين س. غانسولس", "p": ["سوريمونو لتوتويا هوكّي (1780–1850)، تلميذ هوكوساي. كانت السوريمونو مطبوعات تُطلب طلبًا خاصًا — غالبًا من حلقات الشعر مع قصائدها — وتُطبع بفخامة أكثر من الأوكيو-إي التجارية، بورق جيد وأصباغ معدنية.", "أوشيواكامارو، اسم طفولة البطل ميناموتو نو يوشيتسوني، والراهب المحارب العملاق بنكي. لقاؤهما الشهير مبارزة على جسر غوجو في كيوتو، لكن النزال هنا يصبح دورًا في السوغوروكو: يجلس الفتى هادئًا خلف الرقعة، وبنكي ورمحه على ظهره يحكّ رأسه مهزومًا. يبدو أنه تحوير مرح."], "spots": [["رقعة السوغوروكو", "رقعة على هيئة صندوق عليها قطع بيضاء وسوداء."], ["بنكي يحكّ رأسه", "بكامل درعه يحكّ المهزوم رأسه."], ["أوشيواكامارو", "البطل الفتى جالسًا خلف الرقعة."], ["الرمح", "نصل ناغيناتا بنكي الكبيرة."], ["القصيدة", "أبيات أعلى اليمين — على الأرجح من الحلقة التي طلبت المطبوعة."], ["التوقيع", "توقيع هوكّي في الإطار أسفل اليمين."]]}}};
  Object.keys(A).forEach(id => Object.keys(A[id]).forEach(l => { if (T[l]) T[l][id] = A[id][l]; })); })(window.MUSEUM_PAINT_T);
/* (2026-11-24) Lucas Emil Vorsterman after Adam de Coster, Backgammon Players (The Art Institute of Chicago 1935.146) */
(T => { const A = {"vorsterman": {"ja": {"title": "バックギャモンをする人々（夜の場面）", "artist": "リュカス・エミール・フォルステルマン（アダム・デ・コステルの原画による）", "date": "1630年ごろ", "place": "フランドル（アントワープ）", "game": "バックギャモン", "medium": "エングレーヴィング、象牙色の紙", "size": "図25.5×34.4cm", "credit": "バーナード・F・ロジャーズ・コレクション", "p": ["アダム・デ・コステルは、1630年ごろのアントワープで、ろうそくに照らされた夜の場面を得意とした画家でした。同じころ同じ町で、フォルステルマンは人気の画家たちの絵を銅版画にしていました。ルーベンスの弟子だったフォルステルマンは、師と仲たがいしてイギリスへ渡ったあと、明暗の強い、カラヴァッジョ風の版画を作るようになります。", "暗い部屋のテーブルで、男たちがバックギャモンの盤を囲んでいます。デ・コステルの光の扱いにならい、2本のろうそくの炎がテーブルのまわりの顔を照らしています（美術館の解説）。右ではリュートを抱えた若者がこちらを見ています。"], "spots": [["盤", "テーブルの上の、箱形に開いたバックギャモン盤。"], ["ろうそく", "燭台のろうそく。炎が人々の顔を照らします。"], ["パイプの男", "つば広帽の男がパイプをくわえて勝負を見ています。"], ["背を向けた男", "テーブルに手をついて身をのりだす男。"], ["リュートの若者", "リュートを抱えて、こちらに笑いかける若者。"], ["名前", "左下に「A. De Coster pi.（デ・コステル画）」、右下に「Vorsterman」。"]]}, "en": {"title": "Backgammon Players (a night scene)", "artist": "Lucas Emil Vorsterman, after Adam de Coster", "date": "c. 1630", "place": "Flanders (Antwerp)", "game": "Backgammon", "medium": "Engraving on ivory paper", "size": "Image 25.5 × 34.4 cm", "credit": "Bernard F. Rogers Collection", "p": ["Adam de Coster was a leading painter of candlelit night scenes in Antwerp around 1630, when Vorsterman, in the same city, was engraving works after popular contemporaries. A pupil of Rubens, Vorsterman fell out with his master and went to England, after which he made stronger, more stylized, Caravaggesque engravings like this one.", "Around a table in a dark room, men gather over a backgammon board. Following De Coster’s handling of light, two candle flames light up the faces around the table (the museum’s note). On the right a young lute player looks out at us."], "spots": [["The board", "A backgammon board opened like a box on the table."], ["The candle", "A candle in its holder; its flame lights the faces."], ["The man with the pipe", "In a broad hat, he smokes and watches the game."], ["The man from behind", "Leaning over, hands on the table."], ["The lute player", "A youth with a lute, smiling out at us."], ["The names", "“A. De Coster pi.” at lower left, “Vorsterman” at lower right."]]}, "zh": {"title": "玩双陆的人（夜景）", "artist": "卢卡斯·埃米尔·福斯特曼（据亚当·德·科斯特原画）", "date": "约1630年", "place": "佛兰德（安特卫普）", "game": "双陆（西洋双陆棋）", "medium": "雕刻凹版，象牙色纸", "size": "画面25.5×34.4厘米", "credit": "伯纳德·F·罗杰斯收藏", "p": ["亚当·德·科斯特是1630年前后安特卫普擅长烛光夜景的画家。同一时期，福斯特曼在同一座城市把当红画家的作品刻成版画。他是鲁本斯的学生，与老师失和、去英国之后，开始制作明暗强烈、更具风格化的卡拉瓦乔式版画，这幅就是一例。", "昏暗的房间里，男人们围着桌上的双陆棋盘。仿照德·科斯特对光的处理，两支烛火照亮了桌边的面孔（美术馆解说）。右边抱着鲁特琴的少年望向我们。"], "spots": [["棋盘", "桌上像盒子一样打开的双陆棋盘。"], ["蜡烛", "烛台上的蜡烛，火光照亮人们的脸。"], ["抽烟斗的男人", "戴宽檐帽的男人叼着烟斗看棋。"], ["背对的男人", "双手撑桌、探身向前的男人。"], ["弹鲁特琴的少年", "抱着鲁特琴、朝我们微笑的少年。"], ["署名", "左下“A. De Coster pi.”，右下“Vorsterman”。"]]}, "zh-TW": {"title": "玩雙陸的人（夜景）", "artist": "盧卡斯·埃米爾·福斯特曼（據亞當·德·科斯特原畫）", "date": "約1630年", "place": "法蘭德斯（安特衛普）", "game": "雙陸（西洋雙陸棋）", "medium": "雕刻凹版，象牙色紙", "size": "畫面25.5×34.4公分", "credit": "伯納德·F·羅傑斯收藏", "p": ["亞當·德·科斯特是1630年前後安特衛普擅長燭光夜景的畫家。同一時期，福斯特曼在同一座城市把當紅畫家的作品刻成版畫。他是魯本斯的學生，與老師失和、去英國之後，開始製作明暗強烈、更具風格化的卡拉瓦喬式版畫，這幅就是一例。", "昏暗的房間裡，男人們圍著桌上的雙陸棋盤。仿照德·科斯特對光的處理，兩支燭火照亮了桌邊的面孔（美術館解說）。右邊抱著魯特琴的少年望向我們。"], "spots": [["棋盤", "桌上像盒子一樣打開的雙陸棋盤。"], ["蠟燭", "燭台上的蠟燭，火光照亮人們的臉。"], ["抽菸斗的男人", "戴寬簷帽的男人叼著菸斗看棋。"], ["背對的男人", "雙手撐桌、探身向前的男人。"], ["彈魯特琴的少年", "抱著魯特琴、朝我們微笑的少年。"], ["署名", "左下「A. De Coster pi.」，右下「Vorsterman」。"]]}, "ko": {"title": "백개먼을 하는 사람들(밤 장면)", "artist": "루카스 에밀 포르스테르만(아담 더 코스테르의 원화에 따름)", "date": "1630년경", "place": "플랑드르(안트베르펜)", "game": "백개먼", "medium": "인그레이빙, 상아색 종이", "size": "화면 25.5×34.4cm", "credit": "버나드 F. 로저스 컬렉션", "p": ["아담 더 코스테르는 1630년경 안트베르펜에서 촛불이 비추는 밤 장면으로 이름난 화가였습니다. 같은 무렵 같은 도시에서 포르스테르만은 인기 화가들의 그림을 동판화로 옮기고 있었습니다. 루벤스의 제자였던 그는 스승과 사이가 틀어져 영국으로 건너간 뒤, 명암이 강하고 양식화된 카라바조풍 판화를 만들게 됩니다.", "어두운 방의 탁자에서 남자들이 백개먼 판을 둘러싸고 있습니다. 더 코스테르의 빛 처리를 본받아, 두 촛불이 탁자 둘레의 얼굴들을 비춥니다(미술관 해설). 오른쪽에서는 류트를 안은 젊은이가 이쪽을 바라봅니다."], "spots": [["판", "탁자 위에 상자처럼 펼친 백개먼 판."], ["촛불", "촛대의 촛불. 불빛이 사람들의 얼굴을 비춥니다."], ["파이프의 남자", "챙 넓은 모자의 남자가 파이프를 물고 승부를 봅니다."], ["등을 보인 남자", "탁자에 손을 짚고 몸을 내민 남자."], ["류트의 젊은이", "류트를 안고 이쪽에 웃어 보이는 젊은이."], ["이름", "왼쪽 아래 ‘A. De Coster pi.’, 오른쪽 아래 ‘Vorsterman’."]]}, "es": {"title": "Jugadores de chaquete (escena nocturna)", "artist": "Lucas Emil Vorsterman, según Adam de Coster", "date": "h. 1630", "place": "Flandes (Amberes)", "game": "Backgammon", "medium": "Grabado a buril sobre papel marfil", "size": "Imagen 25,5 × 34,4 cm", "credit": "Colección Bernard F. Rogers", "p": ["Adam de Coster fue un destacado pintor de escenas nocturnas a la luz de las velas en la Amberes de hacia 1630, cuando Vorsterman, en la misma ciudad, grababa obras de contemporáneos populares. Discípulo de Rubens, Vorsterman se enemistó con su maestro y se fue a Inglaterra, tras lo cual hizo grabados más contrastados, estilizados y caravaggescos como este.", "En torno a una mesa en un cuarto oscuro, unos hombres se reúnen ante un tablero de backgammon. Siguiendo el manejo de la luz de De Coster, dos velas iluminan los rostros alrededor de la mesa (nota del museo). A la derecha, un joven laudista nos mira."], "spots": [["El tablero", "Un tablero de backgammon abierto como una caja sobre la mesa."], ["La vela", "Una vela en su candelero: su llama ilumina los rostros."], ["El hombre de la pipa", "Con sombrero ancho, fuma y mira la partida."], ["El hombre de espaldas", "Inclinado, con las manos en la mesa."], ["El laudista", "Un joven con un laúd que nos sonríe."], ["Los nombres", "«A. De Coster pi.» abajo a la izquierda, «Vorsterman» abajo a la derecha."]]}, "fr": {"title": "Joueurs de trictrac (scène nocturne)", "artist": "Lucas Emil Vorsterman, d’après Adam de Coster", "date": "v. 1630", "place": "Flandre (Anvers)", "game": "Backgammon", "medium": "Gravure au burin sur papier ivoire", "size": "Image 25,5 × 34,4 cm", "credit": "Collection Bernard F. Rogers", "p": ["Adam de Coster était, vers 1630 à Anvers, un peintre réputé de scènes nocturnes à la chandelle, au moment où Vorsterman, dans la même ville, gravait les œuvres de contemporains en vogue. Élève de Rubens, Vorsterman se brouilla avec son maître et partit en Angleterre ; il fit ensuite des gravures plus contrastées, plus stylisées, caravagesques, comme celle-ci.", "Autour d’une table dans une pièce sombre, des hommes se penchent sur un plateau de trictrac. À la manière de De Coster, deux flammes de chandelle éclairent les visages autour de la table (notice du musée). À droite, un jeune joueur de luth nous regarde."], "spots": [["Le plateau", "Un trictrac ouvert comme une boîte sur la table."], ["La chandelle", "Une chandelle sur son bougeoir ; sa flamme éclaire les visages."], ["L’homme à la pipe", "Coiffé d’un large chapeau, il fume en regardant la partie."], ["L’homme de dos", "Penché, les mains sur la table."], ["Le joueur de luth", "Un jeune homme au luth qui nous sourit."], ["Les noms", "« A. De Coster pi. » en bas à gauche, « Vorsterman » en bas à droite."]]}, "pt": {"title": "Jogadores de gamão (cena noturna)", "artist": "Lucas Emil Vorsterman, segundo Adam de Coster", "date": "c. 1630", "place": "Flandres (Antuérpia)", "game": "Gamão", "medium": "Gravura a buril sobre papel marfim", "size": "Imagem 25,5 × 34,4 cm", "credit": "Coleção Bernard F. Rogers", "p": ["Adam de Coster foi um destacado pintor de cenas noturnas à luz de velas na Antuérpia de cerca de 1630, quando Vorsterman, na mesma cidade, gravava obras de contemporâneos populares. Discípulo de Rubens, Vorsterman zangou-se com o mestre e partiu para Inglaterra, passando depois a fazer gravuras mais contrastadas, estilizadas e caravaggescas como esta.", "Em volta de uma mesa numa sala escura, homens reúnem-se diante de um tabuleiro de gamão. Seguindo o tratamento da luz de De Coster, duas chamas de vela iluminam os rostos à volta da mesa (nota do museu). À direita, um jovem tocador de alaúde olha para nós."], "spots": [["O tabuleiro", "Um tabuleiro de gamão aberto como uma caixa sobre a mesa."], ["A vela", "Uma vela no castiçal: a chama ilumina os rostos."], ["O homem do cachimbo", "De chapéu largo, fuma e observa o jogo."], ["O homem de costas", "Inclinado, com as mãos na mesa."], ["O tocador de alaúde", "Um jovem com um alaúde, a sorrir para nós."], ["Os nomes", "«A. De Coster pi.» em baixo à esquerda, «Vorsterman» em baixo à direita."]]}, "de": {"title": "Tricktrackspieler (Nachtszene)", "artist": "Lucas Emil Vorsterman, nach Adam de Coster", "date": "um 1630", "place": "Flandern (Antwerpen)", "game": "Backgammon", "medium": "Kupferstich auf elfenbeinfarbenem Papier", "size": "Bild 25,5 × 34,4 cm", "credit": "Bernard F. Rogers Collection", "p": ["Adam de Coster war um 1630 in Antwerpen ein führender Maler kerzenbeleuchteter Nachtszenen, als Vorsterman in derselben Stadt Werke beliebter Zeitgenossen stach. Der Rubens-Schüler überwarf sich mit seinem Meister und ging nach England; danach schuf er kräftigere, stilisierte, caravaggeske Stiche wie diesen.", "Um einen Tisch in einem dunklen Raum beugen sich Männer über ein Tricktrackbrett. Nach De Costers Lichtführung erhellen zwei Kerzenflammen die Gesichter am Tisch (Museumstext). Rechts blickt ein junger Lautenspieler zu uns heraus."], "spots": [["Das Brett", "Ein wie ein Kasten aufgeklapptes Brett auf dem Tisch."], ["Die Kerze", "Eine Kerze im Leuchter; ihre Flamme erhellt die Gesichter."], ["Der Mann mit Pfeife", "Mit breitem Hut raucht er und schaut zu."], ["Der Mann von hinten", "Vorgebeugt, die Hände auf dem Tisch."], ["Der Lautenspieler", "Ein Jüngling mit Laute, der uns anlächelt."], ["Die Namen", "„A. De Coster pi.“ unten links, „Vorsterman“ unten rechts."]]}, "ru": {"title": "Игроки в нарды (ночная сцена)", "artist": "Лукас Эмиль Ворстерман, по картине Адама де Костера", "date": "Ок. 1630", "place": "Фландрия (Антверпен)", "game": "Нарды (бэкгаммон)", "medium": "Резцовая гравюра на бумаге цвета слоновой кости", "size": "Изображение 25,5 × 34,4 см", "credit": "Собрание Бернарда Ф. Роджерса", "p": ["Адам де Костер около 1630 года был в Антверпене известным мастером ночных сцен при свечах; тогда же Ворстерман в том же городе гравировал работы популярных современников. Ученик Рубенса, он поссорился с учителем и уехал в Англию, после чего стал делать более контрастные, стилизованные, караваджистские гравюры, как эта.", "За столом в тёмной комнате мужчины собрались над доской для нард. Вслед за де Костером два огонька свечей освещают лица вокруг стола (пояснение музея). Справа юноша с лютней смотрит на нас."], "spots": [["Доска", "Доска для нард, раскрытая как ящик, на столе."], ["Свеча", "Свеча в подсвечнике; её пламя освещает лица."], ["Мужчина с трубкой", "В широкой шляпе, курит и следит за игрой."], ["Мужчина со спины", "Наклонился, опираясь руками о стол."], ["Юноша с лютней", "Юноша с лютней улыбается нам."], ["Имена", "«A. De Coster pi.» внизу слева, «Vorsterman» внизу справа."]]}, "tr": {"title": "Tavla Oyuncuları (gece sahnesi)", "artist": "Lucas Emil Vorsterman, Adam de Coster’den", "date": "y. 1630", "place": "Flandre (Anvers)", "game": "Tavla", "medium": "Fildişi rengi kâğıt üzerine gravür", "size": "Görüntü 25,5 × 34,4 cm", "credit": "Bernard F. Rogers Koleksiyonu", "p": ["Adam de Coster, 1630 dolaylarında Anvers’te mum ışığında gece sahneleriyle tanınan bir ressamdı; aynı dönemde aynı kentte Vorsterman, popüler çağdaşlarının eserlerini gravüre aktarıyordu. Rubens’in öğrencisi olan Vorsterman ustasıyla bozuşup İngiltere’ye gittikten sonra, bunun gibi daha güçlü, üslupçu, Caravaggio tarzı gravürler yaptı.", "Karanlık bir odada bir masanın çevresinde adamlar tavla tahtasının başına toplanmış. De Coster’in ışık kullanımını izleyerek iki mum alevi masadaki yüzleri aydınlatıyor (müze notu). Sağda lavtalı bir genç bize bakıyor."], "spots": [["Tahta", "Masada kutu gibi açılmış bir tavla."], ["Mum", "Şamdandaki mum; alevi yüzleri aydınlatıyor."], ["Pipolu adam", "Geniş şapkalı, pipo içerek oyunu izliyor."], ["Arkası dönük adam", "Ellerini masaya dayamış, öne eğilmiş."], ["Lavtacı genç", "Lavtasıyla bize gülümseyen bir genç."], ["Adlar", "Sol altta “A. De Coster pi.”, sağ altta “Vorsterman”."]]}, "id": {"title": "Para Pemain Backgammon (adegan malam)", "artist": "Lucas Emil Vorsterman, menurut Adam de Coster", "date": "sekitar 1630", "place": "Flandria (Antwerpen)", "game": "Backgammon", "medium": "Grafir di atas kertas warna gading", "size": "Gambar 25,5 × 34,4 cm", "credit": "Koleksi Bernard F. Rogers", "p": ["Adam de Coster adalah pelukis terkemuka adegan malam bercahaya lilin di Antwerpen sekitar 1630, ketika Vorsterman di kota yang sama mengukir karya pelukis populer sezamannya. Murid Rubens ini berselisih dengan gurunya lalu pergi ke Inggris, dan sesudahnya membuat grafir yang lebih kuat kontrasnya, bergaya, ala Caravaggio seperti ini.", "Di sekeliling meja di ruangan gelap, para pria berkumpul di depan papan backgammon. Mengikuti cara De Coster mengolah cahaya, dua nyala lilin menerangi wajah-wajah di sekitar meja (catatan museum). Di kanan, seorang pemuda pemain lute memandang ke arah kita."], "spots": [["Papan", "Papan backgammon yang terbuka seperti kotak di meja."], ["Lilin", "Lilin di kandilnya; nyalanya menerangi wajah-wajah."], ["Pria berpipa", "Bertopi lebar, ia mengisap pipa sambil menonton."], ["Pria yang membelakangi", "Membungkuk dengan tangan di meja."], ["Pemain lute", "Pemuda dengan lute yang tersenyum pada kita."], ["Nama", "“A. De Coster pi.” di kiri bawah, “Vorsterman” di kanan bawah."]]}, "hi": {"title": "बैकगैमन के खिलाड़ी (रात का दृश्य)", "artist": "लूकास एमिल फ़ोर्स्टरमन, आदम दे कोस्टर के चित्र पर आधारित", "date": "लगभग 1630", "place": "फ़्लैंडर्स (एंटवर्प)", "game": "बैकगैमन", "medium": "हाथीदाँत रंग के काग़ज़ पर उत्कीर्णन", "size": "चित्र 25.5 × 34.4 सेमी", "credit": "बर्नार्ड एफ़. रॉजर्स संग्रह", "p": ["आदम दे कोस्टर लगभग 1630 के एंटवर्प में मोमबत्ती की रोशनी वाले रात के दृश्यों के प्रमुख चित्रकार थे, जब उसी शहर में फ़ोर्स्टरमन लोकप्रिय समकालीनों की कृतियाँ उत्कीर्ण कर रहे थे। रूबेन्स के शिष्य फ़ोर्स्टरमन का अपने गुरु से मनमुटाव हुआ और वे इंग्लैंड गए; उसके बाद उन्होंने इस जैसी अधिक तीखी, शैलीबद्ध, कारावाद्जो जैसी नक़्क़ाशियाँ बनाईं।", "अँधेरे कमरे में एक मेज़ के चारों ओर आदमी बैकगैमन की बिसात पर जुटे हैं। दे कोस्टर की रोशनी की शैली का अनुसरण करते हुए दो मोमबत्तियों की लौ मेज़ के आसपास के चेहरों को रोशन करती है (संग्रहालय की टिप्पणी)। दाईं ओर ल्यूट लिए एक युवक हमारी ओर देखता है।"], "spots": [["बिसात", "मेज़ पर संदूक की तरह खुली बैकगैमन बिसात।"], ["मोमबत्ती", "शमादान में मोमबत्ती; उसकी लौ चेहरों को रोशन करती है।"], ["पाइप वाला आदमी", "चौड़ी टोपी में, पाइप पीते हुए खेल देखता है।"], ["पीठ किए आदमी", "मेज़ पर हाथ टिकाए झुका हुआ।"], ["ल्यूट वादक", "ल्यूट लिए, हमारी ओर मुस्कुराता युवक।"], ["नाम", "नीचे बाईं ओर ‘A. De Coster pi.’, नीचे दाईं ओर ‘Vorsterman’।"]]}, "ar": {"title": "لاعبو الطاولة (مشهد ليلي)", "artist": "لوكاس إميل فورسترمان، عن لوحة لآدم دي كوستر", "date": "نحو 1630", "place": "الفلاندر (أنتويرب)", "game": "الطاولة (باكغامون)", "medium": "حفر بالإزميل على ورق عاجي", "size": "الصورة 25.5 × 34.4 سم", "credit": "مجموعة برنارد ف. روجرز", "p": ["كان آدم دي كوستر رسامًا بارزًا لمشاهد الليل تحت ضوء الشموع في أنتويرب نحو 1630، حين كان فورسترمان في المدينة نفسها يحفر أعمال معاصريه المشهورين. وكان فورسترمان تلميذًا لروبنز، ثم اختلف مع أستاذه وسافر إلى إنجلترا، فصار يصنع بعدها حفريات أقوى تباينًا وأكثر أسلبة على طريقة كارافاجيو مثل هذه.", "حول طاولة في غرفة مظلمة يجتمع رجال أمام رقعة الطاولة. وعلى طريقة دي كوستر في معالجة الضوء، تضيء شعلتا شمعتين الوجوه حول الطاولة (شرح المتحف). وعلى اليمين شاب يحمل عودًا ينظر إلينا."], "spots": [["الرقعة", "رقعة طاولة مفتوحة كالصندوق على الطاولة."], ["الشمعة", "شمعة في شمعدانها، يضيء لهبها الوجوه."], ["صاحب الغليون", "بقبعة عريضة يدخّن ويتابع اللعب."], ["الرجل المولّي ظهره", "منحنٍ ويداه على الطاولة."], ["عازف العود", "شاب يحمل عودًا ويبتسم لنا."], ["الأسماء", "«A. De Coster pi.» أسفل اليسار، و«Vorsterman» أسفل اليمين."]]}}};
  Object.keys(A).forEach(id => Object.keys(A[id]).forEach(l => { if (T[l]) T[l][id] = A[id][l]; })); })(window.MUSEUM_PAINT_T);
