/* (2026-11-25) Follower of Posada, Game of the Coyote (The Art Institute of Chicago 1944.1047) — a fox-and-geese hunt game */
(T => { const A = {"coyote": {"ja": {"title": "コヨーテのゲーム", "artist": "ホセ・グアダルーペ・ポサダの追随者", "date": "年代不明", "place": "メキシコ", "game": "コヨーテとめんどり（キツネとガチョウの仲間）", "medium": "亜鉛凸版、紙", "size": "38.2×30.5cm", "credit": "ウィリアム・マッカリン・マッキー記念基金", "p": ["ポサダがメキシコシティの大衆向けの版元のために作ったものと同じ、亜鉛凸版で刷った遊ぶための一枚刷りです。上に大きく「JUEGO DEL COYOTE（コヨーテのゲーム）」、まわりには鶏小屋をねらうコヨーテや、棒を振り上げて追い払う人が描かれています。下の帯には「イルデフォンソ・T・オレリャーナの所有」とあります。", "下の「EXPLICACION」に遊び方が刷られています。2人で遊び、一方は15のめんどり、もう一方はコヨーテ1匹。めんどりは前と横にしか進めず、後ろへは戻れません。コヨーテはどの向きにも動け、すぐ後ろが空いていればめんどりを跳び越えて食べます。めんどりはコヨーテを囲んで動けなくすれば勝ち。ヨーロッパの「キツネとガチョウ」と同じしくみの追い込みゲームです。"], "spots": [["コヨーテのマス", "中央の円に描かれたコヨーテの顔。ここからコヨーテが始めます。"], ["めんどりのマス", "めんどりの絵の円。ここにめんどりの駒を並べます。"], ["遊び方", "「EXPLICACION」。駒の数や動き方、勝ち負けが書かれています。"], ["題", "「JUEGO DEL COYOTE（コヨーテのゲーム）」。"], ["めんどりをくわえるコヨーテ", "左下では、コヨーテがめんどりをねらっています。"], ["棒を振る人", "右上では、棒を振り上げてコヨーテを追う人。"]]}, "en": {"title": "Game of the Coyote", "artist": "Follower of José Guadalupe Posada", "date": "Undated", "place": "Mexico", "game": "Coyote and hens (a fox-and-geese game)", "medium": "Relief engraving on zinc on paper", "size": "38.2 × 30.5 cm", "credit": "William McCallin McKee Memorial Endowment", "p": ["A single sheet to play on, printed from zinc relief like the sheets Posada made for Mexico City’s popular presses. Across the top runs “JUEGO DEL COYOTE” (game of the coyote); around the board, coyotes raid the henhouse and a man swings a stick to drive one off. The strip below reads “Property of Ildefonso T. Orellana.”", "The rules are printed in the “EXPLICACION” at the bottom: two players, one with fifteen hens and the other with a single coyote. Hens move forward or sideways but never back; the coyote moves in every direction and eats a hen by jumping over it when the point behind is empty. The hens win by hemming the coyote in. It is the same hunt game as Europe’s fox and geese."], "spots": [["The coyote’s point", "The coyote’s head in the central circle: where the coyote starts."], ["The hens’ points", "Circles with hens: where the hen pieces are set out."], ["The rules", "The “EXPLICACION”: pieces, moves, and how to win."], ["The title", "“JUEGO DEL COYOTE” — game of the coyote."], ["A coyote after a hen", "At lower left, a coyote goes for a hen."], ["The man with the stick", "At upper right, a man raises a stick to chase off a coyote."]]}, "zh": {"title": "郊狼棋", "artist": "何塞·瓜达卢佩·波萨达的追随者", "date": "年代不详", "place": "墨西哥", "game": "郊狼与母鸡（狐狸与鹅一类）", "medium": "锌版凸版，纸本", "size": "38.2×30.5厘米", "credit": "威廉·麦卡林·麦基纪念基金", "p": ["这是和波萨达为墨西哥城民间印坊所作的作品一样、用锌版凸版印制的单张游戏纸。上方大字写着“JUEGO DEL COYOTE”（郊狼棋），四周画着偷袭鸡舍的郊狼和挥棍驱赶的人。下方的横条写着“伊尔德丰索·T·奥雷利亚纳所有”。", "下方的“EXPLICACION”印着玩法：两人对弈，一方有15只母鸡，另一方只有一只郊狼。母鸡只能向前或向旁走，不能后退；郊狼可向任何方向走，若母鸡身后是空位，就跳过去把它吃掉。母鸡把郊狼围得动弹不得就赢了。这和欧洲的“狐狸与鹅”是同一类追捕游戏。"], "spots": [["郊狼的位置", "中央圆圈里的郊狼头，郊狼从这里出发。"], ["母鸡的位置", "画着母鸡的圆圈，母鸡棋子摆在这里。"], ["玩法", "“EXPLICACION”，写着棋子数、走法和胜负。"], ["标题", "“JUEGO DEL COYOTE”——郊狼棋。"], ["扑向母鸡的郊狼", "左下，一只郊狼扑向母鸡。"], ["挥棍的人", "右上，一个人举棍驱赶郊狼。"]]}, "zh-TW": {"title": "郊狼棋", "artist": "何塞·瓜達盧佩·波薩達的追隨者", "date": "年代不詳", "place": "墨西哥", "game": "郊狼與母雞（狐狸與鵝一類）", "medium": "鋅版凸版，紙本", "size": "38.2×30.5公分", "credit": "威廉·麥卡林·麥基紀念基金", "p": ["這是和波薩達為墨西哥城民間印坊所作的作品一樣、用鋅版凸版印製的單張遊戲紙。上方大字寫著「JUEGO DEL COYOTE」（郊狼棋），四周畫著偷襲雞舍的郊狼和揮棍驅趕的人。下方的橫條寫著「伊爾德豐索·T·奧雷利亞納所有」。", "下方的「EXPLICACION」印著玩法：兩人對弈，一方有15隻母雞，另一方只有一隻郊狼。母雞只能向前或向旁走，不能後退；郊狼可向任何方向走，若母雞身後是空位，就跳過去把牠吃掉。母雞把郊狼圍得動彈不得就贏了。這和歐洲的「狐狸與鵝」是同一類追捕遊戲。"], "spots": [["郊狼的位置", "中央圓圈裡的郊狼頭，郊狼從這裡出發。"], ["母雞的位置", "畫著母雞的圓圈，母雞棋子擺在這裡。"], ["玩法", "「EXPLICACION」，寫著棋子數、走法和勝負。"], ["標題", "「JUEGO DEL COYOTE」——郊狼棋。"], ["撲向母雞的郊狼", "左下，一隻郊狼撲向母雞。"], ["揮棍的人", "右上，一個人舉棍驅趕郊狼。"]]}, "ko": {"title": "코요테 놀이", "artist": "호세 과달루페 포사다의 추종자", "date": "연대 미상", "place": "멕시코", "game": "코요테와 암탉(여우와 거위 계열)", "medium": "아연 볼록판, 종이", "size": "38.2×30.5cm", "credit": "윌리엄 매컬린 매키 기념 기금", "p": ["포사다가 멕시코시티 대중 인쇄소를 위해 만든 것과 같은 아연 볼록판으로 찍은, 놀이용 한 장짜리 인쇄물입니다. 위에 크게 ‘JUEGO DEL COYOTE(코요테 놀이)’라고 쓰여 있고, 둘레에는 닭장을 노리는 코요테와 막대를 휘둘러 쫓는 사람이 그려져 있습니다. 아래 띠에는 ‘일데폰소 T. 오레야나 소유’라고 적혀 있습니다.", "아래의 ‘EXPLICACION’에 놀이 방법이 인쇄되어 있습니다. 두 사람이 하며, 한쪽은 암탉 15마리, 다른 쪽은 코요테 1마리. 암탉은 앞과 옆으로만 가고 뒤로는 못 갑니다. 코요테는 어느 방향으로나 움직이며, 바로 뒤가 비어 있으면 암탉을 뛰어넘어 잡아먹습니다. 암탉은 코요테를 에워싸 움직이지 못하게 하면 이깁니다. 유럽의 ‘여우와 거위’와 같은 구조의 몰이 놀이입니다."], "spots": [["코요테의 자리", "가운데 원에 그린 코요테 얼굴. 코요테가 여기서 시작합니다."], ["암탉의 자리", "암탉 그림의 원. 여기에 암탉 말을 놓습니다."], ["놀이 방법", "‘EXPLICACION’. 말의 수와 움직임, 승패가 적혀 있습니다."], ["제목", "‘JUEGO DEL COYOTE’ — 코요테 놀이."], ["암탉을 노리는 코요테", "왼쪽 아래에서 코요테가 암탉을 노립니다."], ["막대를 휘두르는 사람", "오른쪽 위에서 막대를 들어 코요테를 쫓는 사람."]]}, "es": {"title": "Juego del Coyote", "artist": "Seguidor de José Guadalupe Posada", "date": "Sin fecha", "place": "México", "game": "Coyote y gallinas (de la familia del zorro y los gansos)", "medium": "Grabado en relieve sobre zinc, impreso en papel", "size": "38,2 × 30,5 cm", "credit": "William McCallin McKee Memorial Endowment", "p": ["Una hoja para jugar, impresa en relieve sobre zinc como las que Posada hacía para las imprentas populares de la Ciudad de México. Arriba se lee «JUEGO DEL COYOTE»; alrededor, coyotes asaltan el gallinero y un hombre blande un palo para ahuyentar a uno. La franja de abajo dice «Propiedad de Ildefonso T. Orellana».", "La EXPLICACION impresa abajo da las reglas: juegan dos personas, una con quince fichas llamadas Gallinas y otra con una, el Coyote. Las gallinas suben y caminan hacia los lados, pero nunca retroceden; el coyote se mueve en todos sentidos y se come una gallina saltando sobre ella si detrás hay lugar vacío. Las gallinas ganan si logran encerrar al coyote. Es el mismo juego de caza que el europeo del zorro y los gansos."], "spots": [["El lugar del coyote", "La cabeza del coyote en el círculo central: allí empieza el coyote."], ["Los lugares de las gallinas", "Círculos con gallinas: allí se colocan sus fichas."], ["La explicación", "La «EXPLICACION»: fichas, movimientos y cómo se gana."], ["El título", "«JUEGO DEL COYOTE»."], ["Un coyote tras una gallina", "Abajo a la izquierda, un coyote va por una gallina."], ["El hombre del palo", "Arriba a la derecha, un hombre alza un palo contra un coyote."]]}, "fr": {"title": "Le Jeu du coyote", "artist": "Suiveur de José Guadalupe Posada", "date": "Non daté", "place": "Mexique", "game": "Coyote et poules (famille du renard et des oies)", "medium": "Gravure en relief sur zinc, sur papier", "size": "38,2 × 30,5 cm", "credit": "William McCallin McKee Memorial Endowment", "p": ["Une feuille à jouer, imprimée en relief sur zinc comme celles que Posada faisait pour les presses populaires de Mexico. En haut, « JUEGO DEL COYOTE » (jeu du coyote) ; tout autour, des coyotes attaquent le poulailler et un homme brandit un bâton pour en chasser un. La bande du bas indique « Propriété d’Ildefonso T. Orellana ».", "La règle est imprimée dans l’« EXPLICACION » en bas : deux joueurs, l’un avec quinze poules, l’autre avec un seul coyote. Les poules avancent ou vont de côté mais ne reculent jamais ; le coyote se déplace en tous sens et mange une poule en sautant par-dessus si la place derrière est libre. Les poules gagnent en enfermant le coyote. C’est le même jeu de chasse que le renard et les oies européen."], "spots": [["La place du coyote", "La tête de coyote dans le cercle central : le coyote part de là."], ["Les places des poules", "Les cercles aux poules : on y pose leurs pions."], ["La règle", "L’« EXPLICACION » : pions, déplacements et victoire."], ["Le titre", "« JUEGO DEL COYOTE » — jeu du coyote."], ["Un coyote sur une poule", "En bas à gauche, un coyote s’en prend à une poule."], ["L’homme au bâton", "En haut à droite, un homme lève un bâton contre un coyote."]]}, "pt": {"title": "Jogo do Coiote", "artist": "Seguidor de José Guadalupe Posada", "date": "Sem data", "place": "México", "game": "Coiote e galinhas (da família da raposa e dos gansos)", "medium": "Gravura em relevo sobre zinco, em papel", "size": "38,2 × 30,5 cm", "credit": "William McCallin McKee Memorial Endowment", "p": ["Uma folha para jogar, impressa em relevo sobre zinco como as que Posada fazia para as tipografias populares da Cidade do México. Em cima lê-se «JUEGO DEL COYOTE» (jogo do coiote); à volta, coiotes assaltam o galinheiro e um homem brande um pau para afugentar um. A faixa de baixo diz «Propriedade de Ildefonso T. Orellana».", "As regras estão impressas na «EXPLICACION» em baixo: dois jogadores, um com quinze galinhas e outro com um só coiote. As galinhas avançam ou andam para os lados, mas nunca recuam; o coiote move-se em todas as direções e come uma galinha saltando por cima dela se atrás houver lugar vazio. As galinhas ganham se encurralarem o coiote. É o mesmo jogo de caça que o europeu da raposa e dos gansos."], "spots": [["O lugar do coiote", "A cabeça do coiote no círculo central: aí começa o coiote."], ["Os lugares das galinhas", "Círculos com galinhas: aí se põem as suas peças."], ["As regras", "A «EXPLICACION»: peças, movimentos e como ganhar."], ["O título", "«JUEGO DEL COYOTE» — jogo do coiote."], ["Um coiote atrás de uma galinha", "Em baixo à esquerda, um coiote vai a uma galinha."], ["O homem do pau", "Em cima à direita, um homem ergue um pau contra um coiote."]]}, "de": {"title": "Das Kojotenspiel", "artist": "Nachfolger von José Guadalupe Posada", "date": "Undatiert", "place": "Mexiko", "game": "Kojote und Hennen (Familie von Fuchs und Gänse)", "medium": "Hochdruck von Zinkplatte auf Papier", "size": "38,2 × 30,5 cm", "credit": "William McCallin McKee Memorial Endowment", "p": ["Ein Spielbogen im Zinkhochdruck, wie Posada sie für die Volksdruckereien von Mexiko-Stadt schuf. Oben steht „JUEGO DEL COYOTE“ (Kojotenspiel); ringsum überfallen Kojoten den Hühnerstall, und ein Mann schwingt einen Stock, um einen zu vertreiben. Der Streifen unten lautet „Eigentum von Ildefonso T. Orellana“.", "Die Regeln stehen in der „EXPLICACION“ unten: zwei Spieler, einer mit fünfzehn Hennen, der andere mit einem einzigen Kojoten. Die Hennen ziehen vorwärts oder seitwärts, nie zurück; der Kojote zieht in alle Richtungen und frisst eine Henne, indem er sie überspringt, wenn der Punkt dahinter frei ist. Die Hennen gewinnen, wenn sie den Kojoten einsperren. Es ist dasselbe Jagdspiel wie das europäische Fuchs und Gänse."], "spots": [["Der Platz des Kojoten", "Der Kojotenkopf im mittleren Kreis: Hier beginnt der Kojote."], ["Die Plätze der Hennen", "Kreise mit Hennen: Hier werden ihre Steine aufgestellt."], ["Die Regeln", "Die „EXPLICACION“: Steine, Züge und Sieg."], ["Der Titel", "„JUEGO DEL COYOTE“ – das Kojotenspiel."], ["Ein Kojote auf Hennenjagd", "Unten links geht ein Kojote auf eine Henne los."], ["Der Mann mit dem Stock", "Oben rechts hebt ein Mann den Stock gegen einen Kojoten."]]}, "ru": {"title": "Игра в койота", "artist": "Последователь Хосе Гуадалупе Посады", "date": "Без даты", "place": "Мексика", "game": "Койот и куры (из семейства «лиса и гуси»)", "medium": "Высокая печать с цинковой доски на бумаге", "size": "38,2 × 30,5 см", "credit": "Мемориальный фонд Уильяма Маккаллина Макки", "p": ["Лист для игры, отпечатанный с цинкового рельефа — так же, как листы, которые Посада делал для народных типографий Мехико. Вверху написано «JUEGO DEL COYOTE» (игра в койота); вокруг койоты нападают на курятник, а человек замахивается палкой, прогоняя одного. На полосе внизу: «Собственность Ильдефонсо Т. Орельяны».", "Правила напечатаны в «EXPLICACION» внизу: играют двое, у одного пятнадцать кур, у другого один койот. Куры ходят вперёд и в стороны, но никогда назад; койот ходит во все стороны и съедает курицу, перепрыгивая через неё, если за ней пусто. Куры побеждают, заперев койота. Это та же охотничья игра, что и европейская «лиса и гуси»."], "spots": [["Место койота", "Голова койота в центральном круге: отсюда начинает койот."], ["Места кур", "Круги с курами: сюда ставят их фишки."], ["Правила", "«EXPLICACION»: фишки, ходы и условия победы."], ["Название", "«JUEGO DEL COYOTE» — игра в койота."], ["Койот за курицей", "Внизу слева койот бросается на курицу."], ["Человек с палкой", "Вверху справа человек поднимает палку на койота."]]}, "tr": {"title": "Çakal Oyunu", "artist": "José Guadalupe Posada’nın bir takipçisi", "date": "Tarihsiz", "place": "Meksika", "game": "Çakal ve tavuklar (tilki ve kazlar ailesinden)", "medium": "Kâğıt üzerine çinko kabartma baskı", "size": "38,2 × 30,5 cm", "credit": "William McCallin McKee Memorial Endowment", "p": ["Posada’nın Mexico City’deki halk matbaaları için yaptıkları gibi çinko kabartmayla basılmış, üzerinde oynanan tek yapraklık bir baskı. Üstte “JUEGO DEL COYOTE” (çakal oyunu) yazar; çevrede çakallar kümese saldırıyor, bir adam da birini kovmak için sopa sallıyor. Alttaki şeritte “Ildefonso T. Orellana’nın mülküdür” yazar.", "Kurallar alttaki “EXPLICACION”da basılıdır: iki kişi oynar; birinde on beş tavuk, ötekinde tek bir çakal vardır. Tavuklar ileri ya da yana gider ama asla geri dönmez; çakal her yöne gider ve arkası boşsa bir tavuğun üzerinden atlayarak onu yer. Tavuklar çakalı kıstırırsa kazanır. Avrupa’daki tilki ve kazlar ile aynı av oyunudur."], "spots": [["Çakalın yeri", "Ortadaki dairede çakal başı: çakal buradan başlar."], ["Tavukların yerleri", "Tavuk resimli daireler: taşlar buraya dizilir."], ["Kurallar", "“EXPLICACION”: taşlar, hamleler ve kazanma."], ["Başlık", "“JUEGO DEL COYOTE” — çakal oyunu."], ["Tavuğa saldıran çakal", "Sol altta bir çakal bir tavuğa saldırıyor."], ["Sopalı adam", "Sağ üstte bir adam bir çakala sopa kaldırıyor."]]}, "id": {"title": "Permainan Koyote", "artist": "Pengikut José Guadalupe Posada", "date": "Tanpa tanggal", "place": "Meksiko", "game": "Koyote dan ayam (sekeluarga dengan rubah dan angsa)", "medium": "Cetak timbul dari pelat seng di atas kertas", "size": "38,2 × 30,5 cm", "credit": "William McCallin McKee Memorial Endowment", "p": ["Lembar untuk bermain, dicetak timbul dari seng seperti lembar-lembar yang dibuat Posada untuk percetakan rakyat Mexico City. Di atas tertulis “JUEGO DEL COYOTE” (permainan koyote); di sekelilingnya, koyote menyerbu kandang ayam dan seorang pria mengayunkan tongkat untuk mengusir salah satunya. Pita di bawah berbunyi “Milik Ildefonso T. Orellana”.", "Aturannya tercetak di “EXPLICACION” di bawah: dua pemain, satu memegang lima belas ayam dan satu lagi seekor koyote. Ayam bergerak maju atau ke samping tetapi tak pernah mundur; koyote bergerak ke segala arah dan memakan ayam dengan melompatinya bila titik di belakangnya kosong. Ayam menang jika berhasil mengurung koyote. Ini permainan berburu yang sama dengan rubah dan angsa dari Eropa."], "spots": [["Tempat koyote", "Kepala koyote di lingkaran tengah: koyote mulai dari sini."], ["Tempat ayam", "Lingkaran bergambar ayam: bidak ayam ditaruh di sini."], ["Aturan", "“EXPLICACION”: bidak, gerakan, dan cara menang."], ["Judul", "“JUEGO DEL COYOTE” — permainan koyote."], ["Koyote mengincar ayam", "Di kiri bawah, seekor koyote menerkam ayam."], ["Pria bertongkat", "Di kanan atas, seorang pria mengangkat tongkat pada koyote."]]}, "hi": {"title": "कोयोटी का खेल", "artist": "होसे ग्वादालूपे पोसादा के एक अनुयायी", "date": "तिथि अज्ञात", "place": "मेक्सिको", "game": "कोयोटी और मुर्ग़ियाँ (लोमड़ी और हंस परिवार)", "medium": "काग़ज़ पर ज़िंक से उभरी छपाई", "size": "38.2 × 30.5 सेमी", "credit": "विलियम मैककैलिन मैकी स्मारक निधि", "p": ["खेलने का एक-पन्ना छापा, जो ज़िंक की उभरी छपाई से वैसे ही छपा है जैसे पोसादा मेक्सिको सिटी के लोक-छापाख़ानों के लिए बनाते थे। ऊपर ‘JUEGO DEL COYOTE’ (कोयोटी का खेल) लिखा है; चारों ओर कोयोटी मुर्ग़ीख़ाने पर धावा बोलते हैं और एक आदमी एक को भगाने के लिए डंडा घुमाता है। नीचे की पट्टी पर लिखा है ‘इल्देफ़ोंसो टी. ओरेयाना की संपत्ति’।", "नियम नीचे ‘EXPLICACION’ में छपे हैं: दो खिलाड़ी, एक के पास पंद्रह मुर्ग़ियाँ और दूसरे के पास एक कोयोटी। मुर्ग़ियाँ आगे या बगल में चलती हैं पर कभी पीछे नहीं; कोयोटी हर दिशा में चलता है और पीछे की जगह ख़ाली हो तो मुर्ग़ी पर कूदकर उसे खा जाता है। मुर्ग़ियाँ कोयोटी को घेर लें तो जीतती हैं। यह यूरोप के ‘लोमड़ी और हंस’ जैसा ही शिकार का खेल है।"], "spots": [["कोयोटी की जगह", "बीच के घेरे में कोयोटी का सिर: कोयोटी यहीं से शुरू करता है।"], ["मुर्ग़ियों की जगहें", "मुर्ग़ी वाले घेरे: यहाँ उनकी गोटियाँ रखी जाती हैं।"], ["नियम", "‘EXPLICACION’: गोटियाँ, चालें और जीत।"], ["शीर्षक", "‘JUEGO DEL COYOTE’ — कोयोटी का खेल।"], ["मुर्ग़ी पर झपटता कोयोटी", "नीचे बाईं ओर एक कोयोटी मुर्ग़ी पर झपटता है।"], ["डंडे वाला आदमी", "ऊपर दाईं ओर एक आदमी कोयोटी पर डंडा उठाता है।"]]}, "ar": {"title": "لعبة القيوط", "artist": "أحد أتباع خوسيه غوادالوبي بوسادا", "date": "بلا تاريخ", "place": "المكسيك", "game": "القيوط والدجاجات (من عائلة الثعلب والإوز)", "medium": "طباعة بارزة من لوح زنك على ورق", "size": "38.2 × 30.5 سم", "credit": "صندوق ويليام ماكالين ماكي التذكاري", "p": ["ورقة للعب مطبوعة طباعة بارزة من الزنك مثل الأوراق التي صنعها بوسادا للمطابع الشعبية في مدينة مكسيكو. في الأعلى «JUEGO DEL COYOTE» (لعبة القيوط)، وحولها قيوطات تهاجم قنّ الدجاج ورجل يلوّح بعصا لطرد أحدها. وعلى الشريط في الأسفل: «ملك إلديفونسو ت. أوريّانا».", "القواعد مطبوعة في «EXPLICACION» أسفل الورقة: لاعبان، مع أحدهما خمس عشرة دجاجة ومع الآخر قيوط واحد. تتقدم الدجاجات إلى الأمام أو إلى الجانب ولا تعود إلى الخلف أبدًا، ويتحرك القيوط في كل الاتجاهات ويأكل الدجاجة بالقفز فوقها إن كانت النقطة خلفها فارغة. وتفوز الدجاجات إذا حاصرت القيوط. إنها لعبة الصيد نفسها التي تُعرف في أوروبا بالثعلب والإوز."], "spots": [["مكان القيوط", "رأس القيوط في الدائرة الوسطى: منها يبدأ القيوط."], ["أماكن الدجاجات", "دوائر عليها دجاجات: هنا توضع قطعها."], ["القواعد", "«EXPLICACION»: القطع والحركات وكيفية الفوز."], ["العنوان", "«JUEGO DEL COYOTE» — لعبة القيوط."], ["قيوط يطارد دجاجة", "في أسفل اليسار قيوط ينقضّ على دجاجة."], ["الرجل ذو العصا", "في أعلى اليمين رجل يرفع عصا على قيوط."]]}}};
  Object.keys(A).forEach(id => Object.keys(A[id]).forEach(l => { if (T[l]) T[l][id] = A[id][l]; })); })(window.MUSEUM_PAINT_T);
