/* (2026-11-25) the Rijksmuseum: Erxleben after "Toioske", Koreans at a board game, from Siebold's Nippon (RP-P-1939-1474) */
(T => { const A = {"koorai": {"ja": {"title": "盤を囲む朝鮮の人々（シーボルト『日本』より）", "artist": "ジェームズ・エルクスレーベン（石版）、「トイオスケ」の原画による", "date": "1832〜52年", "place": "オランダ（ライデン）／朝鮮の人々", "game": "盤の遊び（碁と思われる）", "medium": "トーン・リトグラフ、手彩色", "size": "紙38×55.5cm", "credit": "F・G・ワラー寄贈", "p": ["ドイツ生まれの医師シーボルトが、長崎のオランダ商館にいたころ（1823〜30年）の見聞をもとにライデンで出版した大著『日本（NIPPON）』の一図です。右上に「TAB. I」、下に「KOORAI（高麗）」とあり、オランダ語とドイツ語で「漁師の一家」と添えられています。石版はエルクスレーベン、原画の作者は版に「トイオスケ」と記されています。", "4人の男が地面に座って盤を囲み、左には子どもの手を引く女性、右には長い棒と袋を持つ男が立っています。手前には黒いつば広の帽子（カッ）が置かれています。盤には升目と丸い石が描かれていて、碁（韓国語でパドゥク）と思われますが、記録には「盤の遊び」とだけあります。"], "spots": [["盤", "升目に丸い石。碁（パドゥク）を打っているところと思われます。"], ["黒い帽子", "地面に置かれた、つば広の黒い帽子（カッ）。"], ["母と子", "子どもの手を引いて勝負を見る女性。"], ["立つ男", "長い棒と袋を持って立つ男。"], ["身をかがめる男", "青い上着の男が、盤をのぞき込みます。"], ["題", "「KOORAI（高麗）」、オランダ語とドイツ語で「漁師の一家」。"]]}, "en": {"title": "Koreans at a Board Game (from Siebold’s Nippon)", "artist": "James Erxleben (lithographer), after a design by ‘Toioske’", "date": "1832–52", "place": "Netherlands (Leiden) / people of Korea", "game": "A board game (probably go)", "medium": "Tinted lithograph, hand-coloured", "size": "Sheet 38 × 55.5 cm", "credit": "Gift of F. G. Waller", "p": ["A plate from NIPPON, the great work that the German-born physician Philipp Franz von Siebold published in Leiden from what he had seen at the Dutch trading post in Nagasaki (1823–30). It is marked “TAB. I” at upper right and “KOORAI” (Korea) below, with “a fisherman’s family” in Dutch and German. Erxleben drew it on the stone; the plate names the designer as “Toioske”.", "Four men sit on the ground round a board; on the left a woman leads a small child, on the right a man stands with a long stick and a pouch. A broad-brimmed black hat (gat) lies in front. The board shows a grid and round stones, so it is probably go (baduk in Korean), though the record says only “a board game”."], "spots": [["The board", "A grid with round stones — probably a game of go (baduk)."], ["The black hat", "A broad-brimmed black hat (gat) on the ground."], ["Mother and child", "A woman leading a child, watching the game."], ["The standing man", "A man standing with a long stick and a pouch."], ["The man bending over", "In a blue jacket, he peers at the board."], ["The title", "“KOORAI” (Korea), with “a fisherman’s family” in Dutch and German."]]}, "zh": {"title": "围着棋盘的朝鲜人（选自西博尔德《日本》）", "artist": "詹姆斯·埃克斯莱本（石版），据“Toioske”原画", "date": "1832—52年", "place": "荷兰（莱顿）／朝鲜人", "game": "棋戏（应为围棋）", "medium": "色调石版画，手工上色", "size": "纸张38×55.5厘米", "credit": "F·G·瓦勒捐赠", "p": ["这是德国出生的医生西博尔德根据在长崎荷兰商馆期间（1823—1830年）的见闻、在莱顿出版的巨著《日本》（NIPPON）中的一幅。右上写“TAB. I”，下方写“KOORAI”（高丽），并用荷兰语和德语注明“渔夫一家”。石版由埃克斯莱本绘制，版上注明原画作者为“Toioske”。", "四个男人坐在地上围着棋盘，左边一位女子牵着小孩，右边站着一个拿长棍和袋子的男人。前面地上放着一顶宽檐黑帽（笠子）。棋盘上画着格子和圆形棋子，应是在下围棋（韩语“巴督”），但记录里只写“棋戏”。"], "spots": [["棋盘", "格子上放着圆形棋子，应是在下围棋。"], ["黑帽", "放在地上的宽檐黑帽（笠子）。"], ["母与子", "牵着孩子观看对局的女子。"], ["站着的男人", "拿着长棍和袋子站着的男人。"], ["俯身的男人", "穿蓝上衣的男人俯身看棋盘。"], ["标题", "“KOORAI”（高丽），以及荷兰语和德语的“渔夫一家”。"]]}, "zh-TW": {"title": "圍著棋盤的朝鮮人（選自西博德《日本》）", "artist": "詹姆斯·埃克斯萊本（石版），據「Toioske」原畫", "date": "1832—52年", "place": "荷蘭（萊頓）／朝鮮人", "game": "棋戲（應為圍棋）", "medium": "色調石版畫，手工上色", "size": "紙張38×55.5公分", "credit": "F·G·瓦勒捐贈", "p": ["這是德國出生的醫生西博德根據在長崎荷蘭商館期間（1823—1830年）的見聞、在萊頓出版的巨著《日本》（NIPPON）中的一幅。右上寫「TAB. I」，下方寫「KOORAI」（高麗），並用荷蘭語和德語註明「漁夫一家」。石版由埃克斯萊本繪製，版上註明原畫作者為「Toioske」。", "四個男人坐在地上圍著棋盤，左邊一位女子牽著小孩，右邊站著一個拿長棍和袋子的男人。前面地上放著一頂寬簷黑帽（笠子）。棋盤上畫著格子和圓形棋子，應是在下圍棋（韓語「巴督」），但記錄裡只寫「棋戲」。"], "spots": [["棋盤", "格子上放著圓形棋子，應是在下圍棋。"], ["黑帽", "放在地上的寬簷黑帽（笠子）。"], ["母與子", "牽著孩子觀看對局的女子。"], ["站著的男人", "拿著長棍和袋子站著的男人。"], ["俯身的男人", "穿藍上衣的男人俯身看棋盤。"], ["標題", "「KOORAI」（高麗），以及荷蘭語和德語的「漁夫一家」。"]]}, "ko": {"title": "판을 둘러싼 조선 사람들(지볼트 『일본』에서)", "artist": "제임스 에르크슬레벤(석판), ‘Toioske’의 원화에 따름", "date": "1832~52년", "place": "네덜란드(레이던) / 조선 사람들", "game": "판 놀이(바둑으로 보임)", "medium": "톤 석판화, 손 채색", "size": "종이 38×55.5cm", "credit": "F. G. 발러 기증", "p": ["독일 태생의 의사 지볼트가 나가사키 네덜란드 상관에 있던 시절(1823~30년)의 견문을 바탕으로 레이던에서 펴낸 대작 『일본(NIPPON)』의 한 장입니다. 오른쪽 위에 ‘TAB. I’, 아래에 ‘KOORAI(고려)’라고 적혀 있고, 네덜란드어와 독일어로 ‘어부 가족’이라고 덧붙였습니다. 석판은 에르크슬레벤이 그렸고, 판에는 원화 작가가 ‘Toioske’로 적혀 있습니다.", "네 남자가 땅에 앉아 판을 둘러싸고, 왼쪽에는 아이 손을 잡은 여인, 오른쪽에는 긴 막대와 주머니를 든 남자가 서 있습니다. 앞쪽에는 챙 넓은 검은 갓이 놓여 있습니다. 판에는 칸과 둥근 돌이 그려져 있어 바둑으로 보이지만, 기록에는 ‘판 놀이’라고만 되어 있습니다."], "spots": [["판", "칸 위의 둥근 돌. 바둑을 두는 모습으로 보입니다."], ["검은 갓", "땅에 놓인 챙 넓은 검은 갓."], ["어머니와 아이", "아이 손을 잡고 승부를 보는 여인."], ["서 있는 남자", "긴 막대와 주머니를 들고 선 남자."], ["몸을 숙인 남자", "푸른 저고리의 남자가 판을 들여다봅니다."], ["제목", "‘KOORAI(고려)’, 네덜란드어와 독일어로 ‘어부 가족’."]]}, "es": {"title": "Coreanos ante un juego de tablero (del Nippon de Siebold)", "artist": "James Erxleben (litógrafo), según un diseño de «Toioske»", "date": "1832–52", "place": "Países Bajos (Leiden) / gente de Corea", "game": "Juego de tablero (probablemente go)", "medium": "Litografía a tono, coloreada a mano", "size": "Hoja 38 × 55,5 cm", "credit": "Donación de F. G. Waller", "p": ["Una lámina de NIPPON, la gran obra que el médico de origen alemán Philipp Franz von Siebold publicó en Leiden a partir de lo que vio en la factoría neerlandesa de Nagasaki (1823–30). Lleva «TAB. I» arriba a la derecha y «KOORAI» (Corea) abajo, con «una familia de pescadores» en neerlandés y alemán. Erxleben la dibujó en la piedra; la lámina nombra al diseñador como «Toioske».", "Cuatro hombres sentados en el suelo rodean un tablero; a la izquierda una mujer lleva de la mano a un niño, a la derecha un hombre de pie sostiene un palo largo y una bolsa. Delante hay un sombrero negro de ala ancha (gat). El tablero muestra una cuadrícula y piedras redondas, así que probablemente es go (baduk en coreano), aunque el registro solo dice «un juego de tablero»."], "spots": [["El tablero", "Cuadrícula con piedras redondas: probablemente una partida de go."], ["El sombrero negro", "Un sombrero negro de ala ancha (gat) en el suelo."], ["Madre e hijo", "Una mujer con un niño de la mano mira la partida."], ["El hombre de pie", "De pie, con un palo largo y una bolsa."], ["El hombre inclinado", "Con chaqueta azul, mira el tablero."], ["El título", "«KOORAI» (Corea), con «una familia de pescadores» en neerlandés y alemán."]]}, "fr": {"title": "Coréens autour d’un jeu de plateau (d’après le Nippon de Siebold)", "artist": "James Erxleben (lithographe), d’après un dessin de « Toioske »", "date": "1832–52", "place": "Pays-Bas (Leyde) / Coréens", "game": "Jeu de plateau (sans doute le go)", "medium": "Lithographie teintée, coloriée à la main", "size": "Feuille 38 × 55,5 cm", "credit": "Don de F. G. Waller", "p": ["Une planche de NIPPON, la grande œuvre que le médecin d’origine allemande Philipp Franz von Siebold publia à Leyde d’après ce qu’il avait vu au comptoir néerlandais de Nagasaki (1823–30). Elle porte « TAB. I » en haut à droite et « KOORAI » (Corée) en bas, avec « une famille de pêcheurs » en néerlandais et en allemand. Erxleben l’a dessinée sur pierre ; la planche nomme le dessinateur « Toioske ».", "Quatre hommes assis par terre entourent un plateau ; à gauche une femme tient un petit enfant par la main, à droite un homme debout tient un long bâton et une bourse. Devant, un chapeau noir à large bord (gat) est posé au sol. Le plateau montre un quadrillage et des pierres rondes : sans doute du go (baduk en coréen), bien que la notice dise seulement « un jeu de plateau »."], "spots": [["Le plateau", "Quadrillage et pierres rondes : sans doute une partie de go."], ["Le chapeau noir", "Un chapeau noir à large bord (gat) au sol."], ["Mère et enfant", "Une femme tenant un enfant regarde la partie."], ["L’homme debout", "Debout, avec un long bâton et une bourse."], ["L’homme penché", "En veste bleue, il scrute le plateau."], ["Le titre", "« KOORAI » (Corée), avec « une famille de pêcheurs » en néerlandais et en allemand."]]}, "pt": {"title": "Coreanos em volta de um jogo de tabuleiro (do Nippon de Siebold)", "artist": "James Erxleben (litógrafo), segundo um desenho de «Toioske»", "date": "1832–52", "place": "Países Baixos (Leiden) / coreanos", "game": "Jogo de tabuleiro (provavelmente go)", "medium": "Litografia tonal, colorida à mão", "size": "Folha 38 × 55,5 cm", "credit": "Doação de F. G. Waller", "p": ["Uma prancha de NIPPON, a grande obra que o médico de origem alemã Philipp Franz von Siebold publicou em Leiden a partir do que viu na feitoria neerlandesa de Nagasáqui (1823–30). Traz «TAB. I» em cima à direita e «KOORAI» (Coreia) em baixo, com «uma família de pescadores» em neerlandês e alemão. Erxleben desenhou-a na pedra; a prancha nomeia o desenhador como «Toioske».", "Quatro homens sentados no chão rodeiam um tabuleiro; à esquerda uma mulher leva uma criança pela mão, à direita um homem de pé segura um pau comprido e uma bolsa. À frente, no chão, um chapéu preto de aba larga (gat). O tabuleiro mostra uma quadrícula e pedras redondas, por isso provavelmente é go (baduk em coreano), embora o registo diga apenas «um jogo de tabuleiro»."], "spots": [["O tabuleiro", "Quadrícula com pedras redondas: provavelmente uma partida de go."], ["O chapéu preto", "Um chapéu preto de aba larga (gat) no chão."], ["Mãe e filho", "Uma mulher com uma criança pela mão observa o jogo."], ["O homem de pé", "De pé, com um pau comprido e uma bolsa."], ["O homem inclinado", "De casaco azul, espreita o tabuleiro."], ["O título", "«KOORAI» (Coreia), com «uma família de pescadores» em neerlandês e alemão."]]}, "de": {"title": "Koreaner beim Brettspiel (aus Siebolds Nippon)", "artist": "James Erxleben (Lithograf), nach einem Entwurf von „Toioske“", "date": "1832–52", "place": "Niederlande (Leiden) / Menschen aus Korea", "game": "Brettspiel (wohl Go)", "medium": "Tonlithografie, handkoloriert", "size": "Blatt 38 × 55,5 cm", "credit": "Geschenk von F. G. Waller", "p": ["Eine Tafel aus NIPPON, dem großen Werk, das der in Deutschland geborene Arzt Philipp Franz von Siebold in Leiden nach seinen Eindrücken in der niederländischen Faktorei in Nagasaki (1823–30) veröffentlichte. Oben rechts steht „TAB. I“, unten „KOORAI“ (Korea), dazu niederländisch und deutsch „eine Fischerfamilie“. Erxleben zeichnete sie auf den Stein; als Entwerfer nennt die Tafel „Toioske“.", "Vier Männer sitzen auf dem Boden um ein Brett; links führt eine Frau ein kleines Kind an der Hand, rechts steht ein Mann mit langem Stock und Beutel. Vorn liegt ein breitkrempiger schwarzer Hut (Gat). Das Brett zeigt ein Gitter und runde Steine – wohl Go (koreanisch Baduk), auch wenn der Datensatz nur „ein Brettspiel“ nennt."], "spots": [["Das Brett", "Gitter mit runden Steinen: wohl eine Partie Go."], ["Der schwarze Hut", "Ein breitkrempiger schwarzer Hut (Gat) am Boden."], ["Mutter und Kind", "Eine Frau mit einem Kind an der Hand sieht zu."], ["Der stehende Mann", "Stehend, mit langem Stock und Beutel."], ["Der vorgebeugte Mann", "In blauer Jacke späht er auf das Brett."], ["Der Titel", "„KOORAI“ (Korea), dazu „eine Fischerfamilie“ auf Niederländisch und Deutsch."]]}, "ru": {"title": "Корейцы за настольной игрой (из «Ниппона» Зибольда)", "artist": "Джеймс Эрксклебен (литограф), по рисунку «Тойоскэ»", "date": "1832–52", "place": "Нидерланды (Лейден) / жители Кореи", "game": "Настольная игра (вероятно, го)", "medium": "Тоновая литография, раскрашенная от руки", "size": "Лист 38 × 55,5 см", "credit": "Дар Ф. Г. Валлера", "p": ["Таблица из NIPPON — большого труда, который уроженец Германии врач Филипп Франц фон Зибольд издал в Лейдене по впечатлениям от жизни в нидерландской фактории в Нагасаки (1823–30). Вверху справа «TAB. I», внизу «KOORAI» (Корея) и по-нидерландски и по-немецки «семья рыбака». На камне рисовал Эрксклебен; автором рисунка лист называет «Тойоскэ».", "Четверо мужчин сидят на земле вокруг доски; слева женщина ведёт за руку маленького ребёнка, справа стоит мужчина с длинной палкой и кисетом. Впереди на земле — чёрная широкополая шляпа (кат). На доске видны сетка и круглые камни, так что это, вероятно, го (по-корейски падук), хотя в записи сказано лишь «настольная игра»."], "spots": [["Доска", "Сетка с круглыми камнями — вероятно, партия в го."], ["Чёрная шляпа", "Широкополая чёрная шляпа (кат) на земле."], ["Мать и дитя", "Женщина с ребёнком за руку смотрит на игру."], ["Стоящий мужчина", "Стоит с длинной палкой и кисетом."], ["Склонившийся мужчина", "В синей куртке, вглядывается в доску."], ["Название", "«KOORAI» (Корея) и по-нидерландски и по-немецки «семья рыбака»."]]}, "tr": {"title": "Bir Masa Oyunu Başında Koreliler (Siebold’un Nippon’undan)", "artist": "James Erxleben (taşbaskıcı), “Toioske”nin çiziminden", "date": "1832–52", "place": "Hollanda (Leiden) / Koreliler", "game": "Masa oyunu (büyük olasılıkla go)", "medium": "Tonlu taşbaskı, elle boyanmış", "size": "Kâğıt 38 × 55,5 cm", "credit": "F. G. Waller bağışı", "p": ["Alman doğumlu hekim Philipp Franz von Siebold’un Nagasaki’deki Hollanda ticaret karakolunda (1823–30) gördüklerine dayanarak Leiden’de yayımladığı büyük eser NIPPON’dan bir levha. Sağ üstte “TAB. I”, altta “KOORAI” (Kore) ve Felemenkçe ile Almanca “bir balıkçı ailesi” yazar. Taşa Erxleben çizmiş; levha çizeri “Toioske” olarak anar.", "Dört adam yere oturmuş bir tahtanın çevresinde; solda bir kadın küçük bir çocuğu elinden tutuyor, sağda uzun bir sopa ve kese tutan bir adam ayakta. Önde yerde geniş kenarlı siyah bir şapka (gat) var. Tahtada ızgara ve yuvarlak taşlar görülüyor; büyük olasılıkla go (Korecede baduk), ama kayıtta yalnızca “bir masa oyunu” denir."], "spots": [["Tahta", "Izgara ve yuvarlak taşlar: büyük olasılıkla bir go oyunu."], ["Siyah şapka", "Yerde geniş kenarlı siyah bir şapka (gat)."], ["Anne ve çocuk", "Elinde çocukla oyunu izleyen kadın."], ["Ayaktaki adam", "Uzun sopa ve keseyle ayakta duran adam."], ["Eğilen adam", "Mavi ceketli, tahtaya bakıyor."], ["Başlık", "“KOORAI” (Kore) ve Felemenkçe ile Almanca “bir balıkçı ailesi”."]]}, "id": {"title": "Orang Korea di Depan Permainan Papan (dari Nippon karya Siebold)", "artist": "James Erxleben (litografer), menurut rancangan “Toioske”", "date": "1832–52", "place": "Belanda (Leiden) / orang Korea", "game": "Permainan papan (kemungkinan go)", "medium": "Litografi bernada, diwarnai tangan", "size": "Kertas 38 × 55,5 cm", "credit": "Hibah F. G. Waller", "p": ["Satu lembar dari NIPPON, karya besar dokter kelahiran Jerman Philipp Franz von Siebold yang diterbitkan di Leiden berdasarkan pengamatannya di pos dagang Belanda di Nagasaki (1823–30). Di kanan atas tertulis “TAB. I” dan di bawah “KOORAI” (Korea), dengan “keluarga nelayan” dalam bahasa Belanda dan Jerman. Erxleben menggambarnya di batu; lembar itu menyebut perancangnya “Toioske”.", "Empat pria duduk di tanah mengelilingi papan; di kiri seorang wanita menuntun anak kecil, di kanan seorang pria berdiri dengan tongkat panjang dan kantong. Di depan tergeletak topi hitam bertepi lebar (gat). Papan itu berpetak dengan batu-batu bundar, jadi kemungkinan go (baduk dalam bahasa Korea), meski catatan hanya menyebut “permainan papan”."], "spots": [["Papan", "Petak dengan batu bundar: kemungkinan permainan go."], ["Topi hitam", "Topi hitam bertepi lebar (gat) di tanah."], ["Ibu dan anak", "Wanita yang menuntun anak sambil menonton."], ["Pria yang berdiri", "Berdiri dengan tongkat panjang dan kantong."], ["Pria yang membungkuk", "Berjaket biru, mengamati papan."], ["Judul", "“KOORAI” (Korea), dengan “keluarga nelayan” dalam bahasa Belanda dan Jerman."]]}, "hi": {"title": "बिसात के चारों ओर कोरियाई लोग (ज़ीबोल्ट की ‘निप्पोन’ से)", "artist": "जेम्स एर्क्सलेबेन (लिथोग्राफ़र), ‘तोइओस्के’ के चित्र पर आधारित", "date": "1832–52", "place": "नीदरलैंड्स (लाइडेन) / कोरिया के लोग", "game": "बिसात का खेल (शायद गो)", "medium": "टोन लिथोग्राफ़, हाथ से रंगा", "size": "काग़ज़ 38 × 55.5 सेमी", "credit": "एफ़. जी. वालर का उपहार", "p": ["जर्मनी में जन्मे चिकित्सक फ़िलिप फ़्रांत्स फ़ॉन ज़ीबोल्ट ने नागासाकी के डच व्यापार-केंद्र (1823–30) में देखी चीज़ों के आधार पर लाइडेन से जो विशाल ग्रंथ ‘NIPPON’ छापा, यह उसकी एक प्लेट है। ऊपर दाईं ओर ‘TAB. I’ और नीचे ‘KOORAI’ (कोरिया) लिखा है, साथ में डच और जर्मन में ‘एक मछुआरे का परिवार’। पत्थर पर चित्र एर्क्सलेबेन ने बनाया; प्लेट मूल चित्रकार का नाम ‘तोइओस्के’ बताती है।", "चार आदमी ज़मीन पर बैठकर एक बिसात को घेरे हैं; बाईं ओर एक स्त्री छोटे बच्चे का हाथ थामे है, दाईं ओर एक आदमी लंबी छड़ी और थैली लिए खड़ा है। सामने ज़मीन पर चौड़ी किनारी वाली काली टोपी (गात) पड़ी है। बिसात पर खाने और गोल पत्थर दिखते हैं, इसलिए शायद यह गो (कोरियाई में बादुक) है, हालाँकि रिकॉर्ड में केवल ‘बिसात का खेल’ लिखा है।"], "spots": [["बिसात", "खानों पर गोल पत्थर: शायद गो की बाज़ी।"], ["काली टोपी", "ज़मीन पर चौड़ी किनारी वाली काली टोपी (गात)।"], ["माँ और बच्चा", "बच्चे का हाथ थामे खेल देखती स्त्री।"], ["खड़ा आदमी", "लंबी छड़ी और थैली लिए खड़ा आदमी।"], ["झुका आदमी", "नीली जैकेट में, बिसात में झाँकता हुआ।"], ["शीर्षक", "‘KOORAI’ (कोरिया), साथ में डच और जर्मन में ‘एक मछुआरे का परिवार’।"]]}, "ar": {"title": "كوريون حول لعبة رقعة (من «نيبون» لسيبولد)", "artist": "جيمس إركسليبن (طبّاع حجري)، عن رسم لـ«تويوسكي»", "date": "1832–1852", "place": "هولندا (لايدن) / أهل كوريا", "game": "لعبة رقعة (على الأرجح الغو)", "medium": "طباعة حجرية ملوّنة النبرة، ملوّنة يدويًا", "size": "الورقة 38 × 55.5 سم", "credit": "هدية ف. غ. فالر", "p": ["لوحة من «نيبون» (NIPPON)، العمل الكبير الذي نشره في لايدن الطبيب الألماني المولد فيليب فرانز فون سيبولد استنادًا إلى ما رآه في المركز التجاري الهولندي في ناغاساكي (1823–1830). في أعلى اليمين «TAB. I» وفي الأسفل «KOORAI» (كوريا)، ومعها «أسرة صياد» بالهولندية والألمانية. رسمها إركسليبن على الحجر، وتذكر اللوحة أن واضع الرسم «تويوسكي».", "أربعة رجال جالسون على الأرض حول رقعة؛ على اليسار امرأة تقود طفلًا صغيرًا، وعلى اليمين رجل واقف يحمل عصا طويلة وكيسًا. وأمامهم قبعة سوداء عريضة الحافة (غات) على الأرض. تُظهر الرقعة شبكة وأحجارًا مستديرة، فالأرجح أنها الغو (بادوك بالكورية)، مع أن السجل يقول «لعبة رقعة» فقط."], "spots": [["الرقعة", "شبكة عليها أحجار مستديرة: على الأرجح دور غو."], ["القبعة السوداء", "قبعة سوداء عريضة الحافة (غات) على الأرض."], ["الأم والطفل", "امرأة تمسك بيد طفل وتتابع اللعب."], ["الرجل الواقف", "واقف يحمل عصا طويلة وكيسًا."], ["الرجل المنحني", "بسترة زرقاء ينظر في الرقعة."], ["العنوان", "«KOORAI» (كوريا)، ومعها «أسرة صياد» بالهولندية والألمانية."]]}}};
  Object.keys(A).forEach(id => Object.keys(A[id]).forEach(l => { if (T[l]) T[l][id] = A[id][l]; })); })(window.MUSEUM_PAINT_T);
