(T => { const A = {"cairo": {"ja": {"title": "カフェの前で盤を囲む人々（カイロ）", "artist": "デリエ＆ベシャール（イポリット・デリエ、エミール・ベシャール）", "date": "1869〜90年ごろ", "place": "エジプト（カイロ）", "game": "盤の遊び（チェスと思われる）", "medium": "鶏卵紙プリント", "size": "10.8×16.4cm", "credit": "", "p": ["カイロで写真館を開いていたフランス人の写真家、イポリット・デリエとエミール・ベシャールの写真です。台紙には「エズベキーヤ庭園のそば」という写真館の名と「カイロ（エジプト）」が刷られています。こうした写真は、エジプトを訪れた旅行者が記念に買い求めました。", "格子窓のある店先の地面に男たちが座り、低い台の上の盤を囲んでいます。盤には背の高い駒がいくつも立っていて、チェス（アラビア語でシャトランジ）と思われますが、美術館の記録には「盤の遊び」とだけあります。撮影のため、人びとは動かずにじっとしています。"], "spots": [["盤と駒", "低い台の上の盤。背の高い駒が並び、チェスと思われます。"], ["格子窓", "木の格子をはめた窓。カイロの古い家並みによく見られる作りです。"], ["杖の男", "杖を持って座り、勝負を見る男。"], ["籠", "地面に置かれた編み籠。"], ["見物の子", "うしろから盤をのぞく子ども。"], ["写真館の名", "台紙の「AU JARDIN DE L'ESBÉKIEH」「CAIRE (EGYPTE)」の文字。"]]}, "en": {"title": "People Round a Board Game outside a Café (Cairo)", "artist": "Délié & Béchard (Hippolyte Délié and Émile Béchard)", "date": "c. 1869–90", "place": "Egypt (Cairo)", "game": "A board game (probably chess)", "medium": "Albumen print", "size": "10.8 × 16.4 cm", "credit": "", "p": ["A photograph by Hippolyte Délié and Émile Béchard, French photographers who kept a studio in Cairo. The mount is printed with the studio’s name, “by the Ezbekiyya Garden”, and “Cairo (Egypt)”. Pictures like this were bought by travellers as souvenirs of Egypt.", "Men sit on the ground before a shopfront with a latticed window, gathered round a board on a low stand. Tall pieces stand on the board, so it is probably chess (shatranj in Arabic), though the museum’s record says only “a board game”. Everyone holds still for the long exposure."], "spots": [["Board and pieces", "The board on its low stand, with tall pieces: probably chess."], ["The latticed window", "A window fitted with wooden lattice, typical of old Cairo houses."], ["The man with the stick", "Seated with a stick, watching the game."], ["The basket", "A woven basket on the ground."], ["The watching child", "A child peers at the board from behind."], ["The studio’s name", "“AU JARDIN DE L’ESBÉKIEH” and “CAIRE (EGYPTE)” on the mount."]]}, "zh": {"title": "咖啡馆前围着棋盘的人们（开罗）", "artist": "德利耶与贝夏尔（伊波利特·德利耶、埃米尔·贝夏尔）", "date": "约1869—90年", "place": "埃及（开罗）", "game": "棋戏（应为国际象棋）", "medium": "蛋白照片", "size": "10.8×16.4厘米", "credit": "", "p": ["这是在开罗开设照相馆的法国摄影师伊波利特·德利耶和埃米尔·贝夏尔拍摄的照片。衬板上印着照相馆的名字“埃兹贝基亚花园旁”和“开罗（埃及）”。这类照片是到访埃及的旅客买来做纪念的。", "男人们坐在装着格子窗的店门前的地上，围着矮架上的棋盘。棋盘上立着好几枚高高的棋子，应是国际象棋（阿拉伯语“沙特兰吉”），但美术馆记录只写着“棋戏”。为了拍照，大家都一动不动。"], "spots": [["棋盘与棋子", "矮架上的棋盘，立着高棋子，应是国际象棋。"], ["格子窗", "装着木格子的窗户，开罗老房子常见的样式。"], ["拄杖的男人", "拿着手杖坐着看棋的男人。"], ["篮子", "放在地上的编织篮。"], ["观看的孩子", "从后面探看棋盘的孩子。"], ["照相馆名", "衬板上的“AU JARDIN DE L'ESBÉKIEH”和“CAIRE (EGYPTE)”。"]]}, "zh-TW": {"title": "咖啡館前圍著棋盤的人們（開羅）", "artist": "德利耶與貝夏爾（伊波利特·德利耶、埃米爾·貝夏爾）", "date": "約1869—90年", "place": "埃及（開羅）", "game": "棋戲（應為西洋棋）", "medium": "蛋白照片", "size": "10.8×16.4公分", "credit": "", "p": ["這是在開羅開設照相館的法國攝影師伊波利特·德利耶和埃米爾·貝夏爾拍攝的照片。襯板上印著照相館的名字「埃茲貝基亞花園旁」和「開羅（埃及）」。這類照片是到訪埃及的旅客買來做紀念的。", "男人們坐在裝著格子窗的店門前的地上，圍著矮架上的棋盤。棋盤上立著好幾枚高高的棋子，應是西洋棋（阿拉伯語「沙特蘭吉」），但美術館記錄只寫著「棋戲」。為了拍照，大家都一動不動。"], "spots": [["棋盤與棋子", "矮架上的棋盤，立著高棋子，應是西洋棋。"], ["格子窗", "裝著木格子的窗戶，開羅老房子常見的樣式。"], ["拄杖的男人", "拿著手杖坐著看棋的男人。"], ["籃子", "放在地上的編織籃。"], ["觀看的孩子", "從後面探看棋盤的孩子。"], ["照相館名", "襯板上的「AU JARDIN DE L'ESBÉKIEH」和「CAIRE (EGYPTE)」。"]]}, "ko": {"title": "카페 앞에서 판을 둘러싼 사람들(카이로)", "artist": "델리에 & 베샤르(이폴리트 델리에, 에밀 베샤르)", "date": "1869~90년경", "place": "이집트(카이로)", "game": "판 놀이(체스로 보임)", "medium": "알부민 프린트", "size": "10.8×16.4cm", "credit": "", "p": ["카이로에서 사진관을 운영한 프랑스 사진가 이폴리트 델리에와 에밀 베샤르의 사진입니다. 대지에는 ‘에즈베키야 정원 옆’이라는 사진관 이름과 ‘카이로(이집트)’가 인쇄되어 있습니다. 이런 사진은 이집트를 찾은 여행자들이 기념으로 샀습니다.", "격자창이 있는 가게 앞 땅바닥에 남자들이 앉아 낮은 받침 위의 판을 둘러싸고 있습니다. 판에는 키 큰 말이 여럿 서 있어 체스(아랍어로 샤트란지)로 보이지만, 미술관 기록에는 ‘판 놀이’라고만 되어 있습니다. 촬영을 위해 모두 꼼짝 않고 있습니다."], "spots": [["판과 말", "낮은 받침 위의 판. 키 큰 말이 늘어서 있어 체스로 보입니다."], ["격자창", "나무 격자를 끼운 창. 카이로 옛 집들에 흔한 구조입니다."], ["지팡이의 남자", "지팡이를 들고 앉아 승부를 보는 남자."], ["바구니", "땅에 놓인 엮은 바구니."], ["구경하는 아이", "뒤에서 판을 들여다보는 아이."], ["사진관 이름", "대지의 ‘AU JARDIN DE L'ESBÉKIEH’와 ‘CAIRE (EGYPTE)’."]]}, "es": {"title": "Gente en torno a un juego de tablero ante un café (El Cairo)", "artist": "Délié & Béchard (Hippolyte Délié y Émile Béchard)", "date": "h. 1869–90", "place": "Egipto (El Cairo)", "game": "Juego de tablero (probablemente ajedrez)", "medium": "Copia a la albúmina", "size": "10,8 × 16,4 cm", "credit": "", "p": ["Una fotografía de Hippolyte Délié y Émile Béchard, fotógrafos franceses con estudio en El Cairo. El soporte lleva impreso el nombre del estudio, «junto al jardín de Ezbekiya», y «El Cairo (Egipto)». Los viajeros compraban fotos así como recuerdo de Egipto.", "Unos hombres sentados en el suelo ante una tienda con una ventana de celosía rodean un tablero sobre un soporte bajo. Sobre el tablero hay piezas altas, así que probablemente es ajedrez (shatranj en árabe), aunque el registro del museo dice solo «un juego de tablero». Todos se quedan quietos para la larga exposición."], "spots": [["Tablero y piezas", "El tablero sobre un soporte bajo, con piezas altas: probablemente ajedrez."], ["La ventana de celosía", "Una ventana con celosía de madera, típica de las casas antiguas de El Cairo."], ["El hombre del bastón", "Sentado con un bastón, mira la partida."], ["La cesta", "Una cesta tejida en el suelo."], ["El niño que mira", "Un niño se asoma al tablero desde atrás."], ["El nombre del estudio", "«AU JARDIN DE L’ESBÉKIEH» y «CAIRE (EGYPTE)» en el soporte."]]}, "fr": {"title": "Groupe autour d’un jeu de plateau devant un café (Le Caire)", "artist": "Délié & Béchard (Hippolyte Délié et Émile Béchard)", "date": "v. 1869–90", "place": "Égypte (Le Caire)", "game": "Jeu de plateau (sans doute les échecs)", "medium": "Tirage sur papier albuminé", "size": "10,8 × 16,4 cm", "credit": "", "p": ["Une photographie d’Hippolyte Délié et Émile Béchard, photographes français installés au Caire. Le carton porte le nom de l’atelier, « Au Jardin de l’Esbékieh », et « Caire (Égypte) ». Les voyageurs achetaient ce genre d’images en souvenir de l’Égypte.", "Des hommes assis par terre devant une boutique à fenêtre grillagée entourent un plateau posé sur un support bas. De hautes pièces s’y dressent : sans doute des échecs (chatrandj en arabe), bien que la notice du musée dise seulement « un jeu de plateau ». Chacun reste immobile pour la longue pose."], "spots": [["Plateau et pièces", "Le plateau sur un support bas, aux hautes pièces : sans doute les échecs."], ["La fenêtre grillagée", "Une fenêtre à treillis de bois, typique des vieilles maisons du Caire."], ["L’homme au bâton", "Assis avec un bâton, il suit la partie."], ["Le panier", "Un panier tressé posé au sol."], ["L’enfant qui regarde", "Un enfant regarde le plateau par-derrière."], ["Le nom de l’atelier", "« AU JARDIN DE L’ESBÉKIEH » et « CAIRE (EGYPTE) » sur le carton."]]}, "pt": {"title": "Pessoas em volta de um jogo de tabuleiro à porta de um café (Cairo)", "artist": "Délié & Béchard (Hippolyte Délié e Émile Béchard)", "date": "c. 1869–90", "place": "Egito (Cairo)", "game": "Jogo de tabuleiro (provavelmente xadrez)", "medium": "Prova em albumina", "size": "10,8 × 16,4 cm", "credit": "", "p": ["Uma fotografia de Hippolyte Délié e Émile Béchard, fotógrafos franceses com estúdio no Cairo. O cartão tem impresso o nome do estúdio, «junto ao jardim de Ezbekiya», e «Cairo (Egito)». Os viajantes compravam fotografias assim como recordação do Egito.", "Homens sentados no chão diante de uma loja com janela de gelosia rodeiam um tabuleiro sobre um suporte baixo. Peças altas erguem-se no tabuleiro, por isso provavelmente é xadrez (shatranj em árabe), embora o registo do museu diga apenas «um jogo de tabuleiro». Todos ficam imóveis para a longa exposição."], "spots": [["Tabuleiro e peças", "O tabuleiro num suporte baixo, com peças altas: provavelmente xadrez."], ["A janela de gelosia", "Uma janela com gelosia de madeira, típica das casas antigas do Cairo."], ["O homem do bordão", "Sentado com um bordão, vê o jogo."], ["O cesto", "Um cesto entrançado no chão."], ["A criança que observa", "Uma criança espreita o tabuleiro por trás."], ["O nome do estúdio", "«AU JARDIN DE L’ESBÉKIEH» e «CAIRE (EGYPTE)» no cartão."]]}, "de": {"title": "Menschen um ein Brettspiel vor einem Café (Kairo)", "artist": "Délié & Béchard (Hippolyte Délié und Émile Béchard)", "date": "um 1869–90", "place": "Ägypten (Kairo)", "game": "Brettspiel (wohl Schach)", "medium": "Albuminabzug", "size": "10,8 × 16,4 cm", "credit": "", "p": ["Eine Fotografie von Hippolyte Délié und Émile Béchard, französischen Fotografen mit Atelier in Kairo. Auf dem Karton stehen der Name des Ateliers, „beim Esbekiya-Garten“, und „Kairo (Ägypten)“. Reisende kauften solche Bilder als Andenken an Ägypten.", "Vor einem Laden mit Gitterfenster sitzen Männer auf dem Boden um ein Brett auf einem niedrigen Gestell. Hohe Figuren stehen darauf – wohl Schach (arabisch Schatrandsch), auch wenn der Museumsdatensatz nur „ein Brettspiel“ nennt. Für die lange Belichtung halten alle still."], "spots": [["Brett und Figuren", "Das Brett auf einem niedrigen Gestell, mit hohen Figuren: wohl Schach."], ["Das Gitterfenster", "Ein Fenster mit Holzgitter, typisch für alte Kairoer Häuser."], ["Der Mann mit Stock", "Sitzend, mit Stock, schaut er zu."], ["Der Korb", "Ein geflochtener Korb am Boden."], ["Das zuschauende Kind", "Ein Kind späht von hinten auf das Brett."], ["Der Ateliername", "„AU JARDIN DE L’ESBÉKIEH“ und „CAIRE (EGYPTE)“ auf dem Karton."]]}, "ru": {"title": "Люди за настольной игрой у кафе (Каир)", "artist": "Делье и Бешар (Ипполит Делье и Эмиль Бешар)", "date": "Ок. 1869–90", "place": "Египет (Каир)", "game": "Настольная игра (вероятно, шахматы)", "medium": "Альбуминовый отпечаток", "size": "10,8 × 16,4 см", "credit": "", "p": ["Фотография Ипполита Делье и Эмиля Бешара — французских фотографов с ателье в Каире. На паспарту напечатаны название ателье «У сада Эзбекия» и «Каир (Египет)». Такие снимки покупали на память путешественники.", "Мужчины сидят на земле перед лавкой с решётчатым окном вокруг доски на низкой подставке. На доске стоят высокие фигуры — вероятно, шахматы (по-арабски шатрандж), хотя в записи музея сказано лишь «настольная игра». Ради долгой выдержки все сидят неподвижно."], "spots": [["Доска и фигуры", "Доска на низкой подставке с высокими фигурами — вероятно, шахматы."], ["Решётчатое окно", "Окно с деревянной решёткой, типичное для старых каирских домов."], ["Мужчина с палкой", "Сидит с палкой и следит за игрой."], ["Корзина", "Плетёная корзина на земле."], ["Смотрящий ребёнок", "Ребёнок заглядывает на доску сзади."], ["Название ателье", "«AU JARDIN DE L’ESBÉKIEH» и «CAIRE (EGYPTE)» на паспарту."]]}, "tr": {"title": "Bir Kahvenin Önünde Masa Oyunu Çevresindekiler (Kahire)", "artist": "Délié & Béchard (Hippolyte Délié ve Émile Béchard)", "date": "y. 1869–90", "place": "Mısır (Kahire)", "game": "Masa oyunu (büyük olasılıkla satranç)", "medium": "Albümin baskı", "size": "10,8 × 16,4 cm", "credit": "", "p": ["Kahire’de stüdyo işleten Fransız fotoğrafçılar Hippolyte Délié ve Émile Béchard’ın bir fotoğrafı. Kartonda stüdyonun adı, “Ezbekiye Bahçesi yanında”, ve “Kahire (Mısır)” basılıdır. Mısır’a gelen yolcular bu tür fotoğrafları hatıra olarak alırdı.", "Kafesli pencereli bir dükkânın önünde yere oturmuş adamlar alçak bir sehpadaki tahtanın çevresinde. Tahtada uzun taşlar duruyor; büyük olasılıkla satranç (Arapçada şatranç), ama müze kaydında yalnızca “bir masa oyunu” denir. Uzun pozlama için herkes kıpırdamadan duruyor."], "spots": [["Tahta ve taşlar", "Alçak sehpadaki tahta, uzun taşlarla: büyük olasılıkla satranç."], ["Kafesli pencere", "Ahşap kafesli pencere; eski Kahire evlerine özgü."], ["Sopalı adam", "Elinde sopa, oturmuş oyunu izliyor."], ["Sepet", "Yerde örme bir sepet."], ["İzleyen çocuk", "Arkadan tahtaya bakan bir çocuk."], ["Stüdyonun adı", "Kartondaki “AU JARDIN DE L’ESBÉKIEH” ve “CAIRE (EGYPTE)”."]]}, "id": {"title": "Orang-orang Mengelilingi Permainan Papan di Depan Kedai Kopi (Kairo)", "artist": "Délié & Béchard (Hippolyte Délié dan Émile Béchard)", "date": "sekitar 1869–90", "place": "Mesir (Kairo)", "game": "Permainan papan (kemungkinan catur)", "medium": "Cetak albumen", "size": "10,8 × 16,4 cm", "credit": "", "p": ["Foto karya Hippolyte Délié dan Émile Béchard, fotografer Prancis yang membuka studio di Kairo. Kartonnya bertuliskan nama studio, “dekat Taman Ezbekiya”, dan “Kairo (Mesir)”. Foto semacam ini dibeli para pelancong sebagai kenang-kenangan dari Mesir.", "Para pria duduk di tanah di depan toko berjendela kisi, mengelilingi papan di atas dudukan rendah. Bidak-bidak tinggi berdiri di papan, jadi kemungkinan catur (syatranj dalam bahasa Arab), meski catatan museum hanya menyebut “permainan papan”. Semua diam tak bergerak demi pencahayaan yang lama."], "spots": [["Papan dan bidak", "Papan di dudukan rendah dengan bidak tinggi: kemungkinan catur."], ["Jendela kisi", "Jendela berkisi kayu, khas rumah-rumah lama Kairo."], ["Pria bertongkat", "Duduk memegang tongkat, menonton permainan."], ["Keranjang", "Keranjang anyaman di tanah."], ["Anak yang menonton", "Seorang anak mengintip papan dari belakang."], ["Nama studio", "“AU JARDIN DE L’ESBÉKIEH” dan “CAIRE (EGYPTE)” di karton."]]}, "hi": {"title": "एक कहवाघर के आगे बिसात घेरे लोग (काहिरा)", "artist": "देलिए और बेशार (इपोलित देलिए और एमील बेशार)", "date": "लगभग 1869–90", "place": "मिस्र (काहिरा)", "game": "बिसात का खेल (शायद शतरंज)", "medium": "एल्ब्यूमेन प्रिंट", "size": "10.8 × 16.4 सेमी", "credit": "", "p": ["काहिरा में स्टूडियो चलाने वाले फ़्रांसीसी फ़ोटोग्राफ़र इपोलित देलिए और एमील बेशार की तस्वीर। माउंट पर स्टूडियो का नाम, ‘एज़बेकिया बाग़ के पास’, और ‘काहिरा (मिस्र)’ छपा है। मिस्र आने वाले यात्री ऐसी तस्वीरें यादगार के तौर पर ख़रीदते थे।", "जालीदार खिड़की वाली दुकान के आगे ज़मीन पर बैठे आदमी एक नीची चौकी पर रखी बिसात को घेरे हैं। बिसात पर ऊँचे मोहरे खड़े हैं, इसलिए यह शायद शतरंज (अरबी में शतरंज) है, हालाँकि संग्रहालय के रिकॉर्ड में केवल ‘बिसात का खेल’ लिखा है। लंबे एक्सपोज़र के लिए सब स्थिर बैठे हैं।"], "spots": [["बिसात और मोहरे", "नीची चौकी पर बिसात, ऊँचे मोहरों के साथ: शायद शतरंज।"], ["जालीदार खिड़की", "लकड़ी की जाली वाली खिड़की, पुराने काहिरा के घरों जैसी।"], ["छड़ी वाला आदमी", "छड़ी लिए बैठकर खेल देखता आदमी।"], ["टोकरी", "ज़मीन पर रखी बुनी टोकरी।"], ["देखता बच्चा", "पीछे से बिसात में झाँकता बच्चा।"], ["स्टूडियो का नाम", "माउंट पर ‘AU JARDIN DE L’ESBÉKIEH’ और ‘CAIRE (EGYPTE)’।"]]}, "ar": {"title": "جماعة حول لعبة رقعة أمام مقهى (القاهرة)", "artist": "دولييه وبيشار (إيبوليت دولييه وإميل بيشار)", "date": "نحو 1869–1890", "place": "مصر (القاهرة)", "game": "لعبة رقعة (على الأرجح الشطرنج)", "medium": "طبعة ألبومين", "size": "10.8 × 16.4 سم", "credit": "", "p": ["صورة لإيبوليت دولييه وإميل بيشار، مصوّرَين فرنسيَّين كان لهما استوديو في القاهرة. على الكرتون اسم الاستوديو «عند حديقة الأزبكية» و«القاهرة (مصر)». وكان المسافرون يشترون مثل هذه الصور تذكارًا من مصر.", "رجال جالسون على الأرض أمام دكان بنافذة مشربية، يحيطون برقعة على حامل منخفض. على الرقعة قطع طويلة قائمة، فالأرجح أنها الشطرنج، مع أن سجل المتحف يقول «لعبة رقعة» فقط. الجميع ساكنون من أجل التعريض الطويل."], "spots": [["الرقعة والقطع", "الرقعة على حامل منخفض بقطع طويلة: على الأرجح الشطرنج."], ["نافذة المشربية", "نافذة بشبكة خشبية، من سمات بيوت القاهرة القديمة."], ["الرجل ذو العصا", "جالس بعصاه يتابع اللعب."], ["السلة", "سلة مجدولة على الأرض."], ["الطفل المتفرّج", "طفل يطل على الرقعة من الخلف."], ["اسم الاستوديو", "«AU JARDIN DE L’ESBÉKIEH» و«CAIRE (EGYPTE)» على الكرتون."]]}}};
  Object.keys(A).forEach(id => Object.keys(A[id]).forEach(l => { if (T[l]) T[l][id] = A[id][l]; })); })(window.MUSEUM_PAINT_T);
