(T => { const A = {"vanmour": {"ja": {"title": "カード遊びをするアルメニア人の集まり", "artist": "ジャン＝バティスト・ヴァンムール", "date": "1720〜37年ごろ", "place": "オスマン帝国（イスタンブール）", "game": "カード遊び", "medium": "油彩・カンヴァス", "size": "44.5×58.5cm", "credit": "", "p": ["フランドル生まれの画家ヴァンムールは、1699年にフランス大使に連れられてイスタンブールへ渡り、亡くなるまでこの都で暮らして、宮廷の行事や町の人びとの暮らしを描きました。この絵の男たちは、服装からアルメニア人だとわかると美術館は記しています。", "大きなろうそくの明かりのもと、男女が赤い布の卓を囲んでカードをしています。卓の上には配られたカード、手に札を持って見入る人もいます。左の隅では年老いた女性が糸を紡いでいます。何という遊びかは記録にありません。"], "spots": [["卓のカード", "赤い布の卓に置かれたカード。"], ["大きなろうそく", "一座を照らす一本のろうそく。"], ["糸を紡ぐ老女", "左の隅で糸を紡ぐ年老いた女性。"], ["札を見る女性", "手札をじっと見る右端の女性。"], ["毛皮の男", "毛皮の縁取りの上着を着た男。服装からアルメニア人とされます。"], ["手を伸ばす人", "卓に身を乗り出してカードを持つ人。"]]}, "en": {"title": "Party of Armenians Playing Cards", "artist": "Jean-Baptiste Vanmour", "date": "c. 1720–37", "place": "Ottoman Empire (Istanbul)", "game": "Cards", "medium": "Oil on canvas", "size": "44.5 × 58.5 cm", "credit": "", "p": ["Born in Flanders, Vanmour went to Istanbul in 1699 with the French ambassador and lived in the city until his death, painting court ceremonies and the daily life of its people. The museum notes that the men’s clothing shows them to be Armenians.", "By the light of a large candle, men and women sit round a table spread with red cloth, playing cards. Cards lie dealt on the table, and some study the hands they hold. In the left corner an old woman is spinning. The record does not say which game it is."], "spots": [["Cards on the table", "Cards laid on the red-covered table."], ["The large candle", "A single candle lights the whole party."], ["The old woman spinning", "An old woman spins in the left corner."], ["A woman with her hand", "At the far right, a woman studies her cards."], ["The man in fur", "A man in a fur-trimmed coat; the clothes mark the men as Armenians."], ["Reaching across", "A figure leans over the table, cards in hand."]]}, "zh": {"title": "打牌的亚美尼亚人聚会", "artist": "让-巴蒂斯特·范穆尔", "date": "约1720—37年", "place": "奥斯曼帝国（伊斯坦布尔）", "game": "纸牌", "medium": "布面油画", "size": "44.5×58.5厘米", "credit": "", "p": ["生于佛兰德的画家范穆尔，1699年随法国大使来到伊斯坦布尔，此后一直住在这座城市直到去世，描绘宫廷典礼和市民生活。美术馆记录说，从衣着可以看出画中的男人是亚美尼亚人。", "在一支大蜡烛的光下，男男女女围着铺红布的桌子打牌。桌上摆着发好的牌，也有人盯着手里的牌。左边角落里，一位老妇人在纺线。记录没有写是哪种牌戏。"], "spots": [["桌上的牌", "铺红布的桌上放着的纸牌。"], ["大蜡烛", "照亮众人的一支蜡烛。"], ["纺线的老妇", "左边角落纺线的老妇人。"], ["看牌的女子", "右端盯着手牌的女子。"], ["穿毛皮的男人", "穿毛皮镶边外衣的男人，衣着表明是亚美尼亚人。"], ["探身的人", "探身向桌、手里拿牌的人。"]]}, "zh-TW": {"title": "打牌的亞美尼亞人聚會", "artist": "讓-巴蒂斯特·范穆爾", "date": "約1720—37年", "place": "鄂圖曼帝國（伊斯坦堡）", "game": "紙牌", "medium": "布面油畫", "size": "44.5×58.5公分", "credit": "", "p": ["生於法蘭德斯的畫家范穆爾，1699年隨法國大使來到伊斯坦堡，此後一直住在這座城市直到去世，描繪宮廷典禮和市民生活。美術館記錄說，從衣著可以看出畫中的男人是亞美尼亞人。", "在一支大蠟燭的光下，男男女女圍著鋪紅布的桌子打牌。桌上擺著發好的牌，也有人盯著手裡的牌。左邊角落裡，一位老婦人在紡線。記錄沒有寫是哪種牌戲。"], "spots": [["桌上的牌", "鋪紅布的桌上放著的紙牌。"], ["大蠟燭", "照亮眾人的一支蠟燭。"], ["紡線的老婦", "左邊角落紡線的老婦人。"], ["看牌的女子", "右端盯著手牌的女子。"], ["穿毛皮的男人", "穿毛皮鑲邊外衣的男人，衣著表明是亞美尼亞人。"], ["探身的人", "探身向桌、手裡拿牌的人。"]]}, "ko": {"title": "카드놀이를 하는 아르메니아인들의 모임", "artist": "장바티스트 반무르", "date": "1720~37년경", "place": "오스만 제국(이스탄불)", "game": "카드놀이", "medium": "캔버스에 유채", "size": "44.5×58.5cm", "credit": "", "p": ["플랑드르 출신 화가 반무르는 1699년 프랑스 대사를 따라 이스탄불로 건너가 세상을 떠날 때까지 이 도시에 살며 궁정 행사와 사람들의 생활을 그렸습니다. 미술관은 남자들의 옷차림으로 보아 아르메니아인임을 알 수 있다고 적고 있습니다.", "커다란 촛불 아래 남녀가 붉은 천을 덮은 탁자에 둘러앉아 카드를 하고 있습니다. 탁자에는 나누어 준 카드가 놓여 있고, 손에 든 패를 들여다보는 사람도 있습니다. 왼쪽 구석에서는 나이 든 여인이 실을 잣고 있습니다. 어떤 놀이인지는 기록에 없습니다."], "spots": [["탁자의 카드", "붉은 천 탁자 위에 놓인 카드."], ["큰 촛불", "모두를 비추는 촛불 하나."], ["실 잣는 노파", "왼쪽 구석에서 실을 잣는 나이 든 여인."], ["패를 보는 여인", "오른쪽 끝에서 손패를 보는 여인."], ["모피 옷의 남자", "모피를 두른 웃옷의 남자. 옷차림으로 아르메니아인으로 봅니다."], ["손을 뻗은 사람", "탁자로 몸을 내밀어 카드를 든 사람."]]}, "es": {"title": "Reunión de armenios jugando a las cartas", "artist": "Jean-Baptiste Vanmour", "date": "h. 1720–37", "place": "Imperio otomano (Estambul)", "game": "Cartas", "medium": "Óleo sobre lienzo", "size": "44,5 × 58,5 cm", "credit": "", "p": ["Nacido en Flandes, Vanmour llegó a Estambul en 1699 con el embajador de Francia y vivió en la ciudad hasta su muerte, pintando ceremonias de la corte y la vida diaria de sus gentes. El museo indica que la ropa de los hombres los identifica como armenios.", "A la luz de una gran vela, hombres y mujeres juegan a las cartas en torno a una mesa cubierta con un paño rojo. Hay cartas repartidas sobre la mesa y algunos estudian las que tienen en la mano. En el rincón izquierdo una anciana hila. El registro no dice de qué juego se trata."], "spots": [["Cartas en la mesa", "Cartas sobre la mesa de paño rojo."], ["La gran vela", "Una sola vela ilumina a todo el grupo."], ["La anciana que hila", "Una anciana hila en el rincón izquierdo."], ["Mujer con sus cartas", "A la derecha, una mujer mira sus cartas."], ["El hombre del abrigo de piel", "Un hombre con abrigo ribeteado de piel; la ropa los señala como armenios."], ["Inclinado sobre la mesa", "Alguien se inclina sobre la mesa con cartas en la mano."]]}, "fr": {"title": "Compagnie d’Arméniens jouant aux cartes", "artist": "Jean-Baptiste Vanmour", "date": "v. 1720–37", "place": "Empire ottoman (Istanbul)", "game": "Cartes", "medium": "Huile sur toile", "size": "44,5 × 58,5 cm", "credit": "", "p": ["Né en Flandre, Vanmour gagna Istanbul en 1699 avec l’ambassadeur de France et vécut dans la ville jusqu’à sa mort, peignant les cérémonies de la cour et la vie de ses habitants. Le musée précise que les vêtements des hommes les désignent comme Arméniens.", "À la lueur d’une grande chandelle, hommes et femmes jouent aux cartes autour d’une table couverte d’un tapis rouge. Des cartes sont distribuées sur la table, et certains scrutent leur jeu. Dans le coin gauche, une vieille femme file. La notice ne dit pas de quel jeu il s’agit."], "spots": [["Cartes sur la table", "Des cartes sur la table au tapis rouge."], ["La grande chandelle", "Une seule chandelle éclaire toute la compagnie."], ["La vieille fileuse", "Une vieille femme file dans le coin gauche."], ["Femme regardant son jeu", "À l’extrême droite, une femme examine ses cartes."], ["L’homme en fourrure", "Un homme au manteau bordé de fourrure ; l’habit désigne des Arméniens."], ["Penché sur la table", "Un personnage se penche sur la table, cartes en main."]]}, "pt": {"title": "Reunião de arménios a jogar às cartas", "artist": "Jean-Baptiste Vanmour", "date": "c. 1720–37", "place": "Império Otomano (Istambul)", "game": "Cartas", "medium": "Óleo sobre tela", "size": "44,5 × 58,5 cm", "credit": "", "p": ["Nascido na Flandres, Vanmour foi para Istambul em 1699 com o embaixador de França e viveu na cidade até morrer, pintando cerimónias da corte e a vida quotidiana dos seus habitantes. O museu indica que as roupas dos homens os identificam como arménios.", "À luz de uma grande vela, homens e mulheres jogam às cartas à volta de uma mesa coberta com um pano vermelho. Há cartas dadas sobre a mesa e alguns estudam as que têm na mão. No canto esquerdo, uma velha fia. O registo não diz que jogo é."], "spots": [["Cartas na mesa", "Cartas sobre a mesa de pano vermelho."], ["A grande vela", "Uma só vela ilumina todo o grupo."], ["A velha a fiar", "Uma velha fia no canto esquerdo."], ["Mulher com as cartas", "À direita, uma mulher olha para as suas cartas."], ["O homem de peles", "Um homem com casaco debruado a peles; a roupa marca-os como arménios."], ["Debruçado sobre a mesa", "Alguém se debruça sobre a mesa com cartas na mão."]]}, "de": {"title": "Armenische Gesellschaft beim Kartenspiel", "artist": "Jean-Baptiste Vanmour", "date": "um 1720–37", "place": "Osmanisches Reich (Istanbul)", "game": "Kartenspiel", "medium": "Öl auf Leinwand", "size": "44,5 × 58,5 cm", "credit": "", "p": ["Der in Flandern geborene Vanmour kam 1699 mit dem französischen Gesandten nach Istanbul und lebte bis zu seinem Tod in der Stadt; er malte Hofzeremonien und den Alltag ihrer Bewohner. Laut Museum zeigt die Kleidung der Männer, dass sie Armenier sind.", "Im Licht einer großen Kerze spielen Männer und Frauen an einem rot gedeckten Tisch Karten. Ausgeteilte Karten liegen auf dem Tisch, manche betrachten ihr Blatt. In der linken Ecke spinnt eine alte Frau. Welches Spiel es ist, sagt der Datensatz nicht."], "spots": [["Karten auf dem Tisch", "Karten auf dem rot gedeckten Tisch."], ["Die große Kerze", "Eine einzige Kerze erhellt die Runde."], ["Die spinnende Alte", "Eine alte Frau spinnt in der linken Ecke."], ["Frau mit ihrem Blatt", "Ganz rechts betrachtet eine Frau ihre Karten."], ["Der Mann im Pelz", "Ein Mann im pelzbesetzten Mantel; die Kleidung weist die Männer als Armenier aus."], ["Über den Tisch gebeugt", "Jemand beugt sich mit Karten in der Hand über den Tisch."]]}, "ru": {"title": "Армяне за карточной игрой", "artist": "Жан-Батист Ванмур", "date": "Ок. 1720–37", "place": "Османская империя (Стамбул)", "game": "Карты", "medium": "Холст, масло", "size": "44,5 × 58,5 см", "credit": "", "p": ["Уроженец Фландрии Ванмур приехал в Стамбул в 1699 году с французским послом и прожил в городе до самой смерти, изображая придворные церемонии и повседневную жизнь горожан. Музей отмечает, что по одежде мужчин видно: это армяне.", "При свете большой свечи мужчины и женщины играют в карты за столом, покрытым красной скатертью. На столе лежат розданные карты, кто-то разглядывает свои. В левом углу старуха прядёт. Какая это игра, в записи не сказано."], "spots": [["Карты на столе", "Карты на столе под красной скатертью."], ["Большая свеча", "Одна свеча освещает всю компанию."], ["Прядущая старуха", "Старуха прядёт в левом углу."], ["Женщина с картами", "Справа женщина рассматривает свои карты."], ["Мужчина в мехах", "Мужчина в кафтане с меховой опушкой; по одежде видно, что это армяне."], ["Склонившийся над столом", "Кто-то склонился над столом с картами в руке."]]}, "tr": {"title": "İskambil Oynayan Ermeni Topluluğu", "artist": "Jean-Baptiste Vanmour", "date": "y. 1720–37", "place": "Osmanlı İmparatorluğu (İstanbul)", "game": "İskambil", "medium": "Tuval üzerine yağlıboya", "size": "44,5 × 58,5 cm", "credit": "", "p": ["Flandre doğumlu Vanmour 1699’da Fransız elçisiyle İstanbul’a geldi ve ölene dek bu şehirde yaşayarak saray törenlerini ve halkın gündelik hayatını resmetti. Müze, erkeklerin giysilerinden Ermeni oldukları anlaşıldığını belirtir.", "Büyük bir mumun ışığında kadınlı erkekli bir grup, kırmızı örtülü bir masanın çevresinde iskambil oynuyor. Masada dağıtılmış kâğıtlar var, bazıları elindeki kâğıtlara bakıyor. Sol köşede yaşlı bir kadın iplik eğiriyor. Kayıtta hangi oyun olduğu yazmıyor."], "spots": [["Masadaki kâğıtlar", "Kırmızı örtülü masadaki iskambil kâğıtları."], ["Büyük mum", "Tüm topluluğu tek bir mum aydınlatıyor."], ["İplik eğiren yaşlı kadın", "Sol köşede iplik eğiren yaşlı kadın."], ["Elindeki kâğıtlara bakan kadın", "En sağda kâğıtlarına bakan bir kadın."], ["Kürklü adam", "Kürk kenarlı kaftanlı adam; giysileri Ermeni olduklarını gösterir."], ["Masaya uzanan", "Elinde kâğıtlarla masaya eğilen biri."]]}, "id": {"title": "Sekelompok Orang Armenia Bermain Kartu", "artist": "Jean-Baptiste Vanmour", "date": "sekitar 1720–37", "place": "Kesultanan Utsmaniyah (Istanbul)", "game": "Kartu", "medium": "Cat minyak di atas kanvas", "size": "44,5 × 58,5 cm", "credit": "", "p": ["Vanmour yang lahir di Flandria pergi ke Istanbul pada 1699 bersama duta besar Prancis dan tinggal di kota itu hingga wafat, melukis upacara istana dan kehidupan sehari-hari warganya. Museum mencatat bahwa dari pakaiannya para pria ini adalah orang Armenia.", "Di bawah cahaya sebatang lilin besar, para pria dan wanita bermain kartu mengelilingi meja berkain merah. Kartu-kartu yang sudah dibagikan tergeletak di meja, dan sebagian memperhatikan kartu di tangan. Di sudut kiri seorang wanita tua memintal benang. Catatan tidak menyebut permainan apa itu."], "spots": [["Kartu di meja", "Kartu di atas meja berkain merah."], ["Lilin besar", "Sebatang lilin menerangi seluruh kelompok."], ["Wanita tua memintal", "Wanita tua memintal di sudut kiri."], ["Wanita melihat kartunya", "Di paling kanan, seorang wanita memandangi kartunya."], ["Pria berbulu", "Pria bermantel berpinggiran bulu; pakaiannya menandai orang Armenia."], ["Mencondongkan badan", "Seseorang condong ke meja dengan kartu di tangan."]]}, "hi": {"title": "ताश खेलती आर्मेनियाई मंडली", "artist": "ज़्याँ-बैप्टिस्ट वानमूर", "date": "लगभग 1720–37", "place": "उस्मानी साम्राज्य (इस्तांबुल)", "game": "ताश", "medium": "कैनवास पर तैलचित्र", "size": "44.5 × 58.5 सेमी", "credit": "", "p": ["फ़्लैंडर्स में जन्मे वानमूर 1699 में फ़्रांसीसी राजदूत के साथ इस्तांबुल गए और जीवन भर वहीं रहकर दरबार के समारोहों और लोगों के रोज़मर्रा जीवन को चित्रित किया। संग्रहालय के अनुसार पुरुषों के कपड़ों से पता चलता है कि वे आर्मेनियाई हैं।", "एक बड़ी मोमबत्ती की रोशनी में स्त्री-पुरुष लाल कपड़े से ढकी मेज़ के चारों ओर ताश खेल रहे हैं। मेज़ पर बाँटे गए पत्ते पड़े हैं, और कुछ लोग हाथ के पत्ते देख रहे हैं। बाएँ कोने में एक बूढ़ी औरत सूत कात रही है। रिकॉर्ड में यह नहीं लिखा कि कौन-सा खेल है।"], "spots": [["मेज़ पर पत्ते", "लाल कपड़े वाली मेज़ पर रखे पत्ते।"], ["बड़ी मोमबत्ती", "पूरी मंडली को रोशन करती एक मोमबत्ती।"], ["सूत कातती बूढ़ी", "बाएँ कोने में सूत कातती बूढ़ी औरत।"], ["पत्ते देखती स्त्री", "दाएँ छोर पर अपने पत्ते देखती स्त्री।"], ["फ़र वाला आदमी", "फ़र की किनारी वाले कोट में आदमी; कपड़े आर्मेनियाई होने का संकेत।"], ["झुककर हाथ बढ़ाता", "हाथ में पत्ते लिए मेज़ पर झुका कोई।"]]}, "ar": {"title": "جماعة من الأرمن يلعبون الورق", "artist": "جان باتيست فانمور", "date": "نحو 1720–1737", "place": "الدولة العثمانية (إسطنبول)", "game": "الورق", "medium": "زيت على قماش", "size": "44.5 × 58.5 سم", "credit": "", "p": ["وُلد فانمور في الفلاندر، وذهب إلى إسطنبول سنة 1699 مع السفير الفرنسي، وعاش في المدينة حتى وفاته يرسم مراسم البلاط وحياة أهلها اليومية. ويذكر المتحف أن ملابس الرجال تدل على أنهم أرمن.", "على ضوء شمعة كبيرة يلعب رجال ونساء الورق حول مائدة مغطاة بقماش أحمر. على المائدة أوراق موزعة، وبعضهم يتأمل الأوراق في يده. وفي الركن الأيسر امرأة عجوز تغزل. لا يذكر السجل أي لعبة هي."], "spots": [["الأوراق على المائدة", "أوراق على المائدة ذات القماش الأحمر."], ["الشمعة الكبيرة", "شمعة واحدة تضيء الجماعة كلها."], ["العجوز الغازلة", "امرأة عجوز تغزل في الركن الأيسر."], ["امرأة تنظر في أوراقها", "في أقصى اليمين امرأة تتأمل أوراقها."], ["الرجل ذو الفراء", "رجل بمعطف محفوف بالفراء؛ تدل الملابس على أنهم أرمن."], ["منحنٍ على المائدة", "شخص ينحني على المائدة والأوراق في يده."]]}}};
  Object.keys(A).forEach(id => Object.keys(A[id]).forEach(l => { if (T[l]) T[l][id] = A[id][l]; })); })(window.MUSEUM_PAINT_T);
